/* ---- src/st_json.h ---- */
/* st_json.h: bounded lexical layer over the safetensors header JSON.
 * Running out of header bytes inside a token is a JSON syntax
 * violation, never truncation: the frame pass has already proven the
 * header bytes are present. Owns the six lexical violation codes.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#ifndef MVET_ST_JSON_H
#define MVET_ST_JSON_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


/* Invariant: start <= index <= end always; positions are absolute file
 * offsets, so violation offsets need no translation. */
typedef struct {
    const uint8_t *buffer; /* whole input, borrowed */
    size_t end;            /* absolute end of the header region */
    size_t index;          /* absolute read position */
    mvet_report_t *report; /* borrowed violation sink */
} mvet_st_json_t;

/* Binds the lexer over the header span. buffer is the whole input,
 * borrowed; header must lie inside it (asserted). */
void mvet_st_json_bind(mvet_st_json_t *json,
                       mvet_report_t *report,
                       const uint8_t *buffer,
                       mvet_span_t header);

/* Advances past the canonical JSON whitespace set (space, tab, LF, CR). */
void mvet_st_json_skip_ws(mvet_st_json_t *json);

/* True when every header byte has been consumed. Pure. */
bool mvet_st_json_at_end(const mvet_st_json_t *json);

/* Reads the current byte without consuming it. Fails as a syntax
 * violation at the header end. */
mvet_istatus_t mvet_st_json_peek(const mvet_st_json_t *json, uint8_t *byte);

/* Consumes exactly token. Fails as a syntax violation otherwise. */
mvet_istatus_t mvet_st_json_expect(mvet_st_json_t *json, uint8_t token);

/* Records a syntax violation at the current position, for grammar
 * errors the walkers detect above the lexical layer. */
mvet_istatus_t mvet_st_json_reject_here(const mvet_st_json_t *json);

/* Reads an object key: a string with escapes rejected (policy, so raw
 * bytes are the duplicate-detection identity), the name-length cap
 * enforced, and strict UTF-8 required. span names the raw content. */
mvet_istatus_t mvet_st_json_read_key(mvet_st_json_t *json, mvet_span_t *span);

/* Reads a string value with full escape validation (including
 * surrogate pairs) and strict UTF-8. span names the raw content. */
mvet_istatus_t mvet_st_json_read_string(mvet_st_json_t *json, mvet_span_t *span);

/* Reads a strict unsigned JSON integer into value: no sign, fraction,
 * exponent, or leading zero, and it must fit u64, exactly the set the
 * canonical usize deserialization accepts on 64-bit. */
mvet_istatus_t mvet_st_json_read_u64(mvet_st_json_t *json, uint64_t *value);

/* Opens a bracketed sequence: consumes open, then detects and consumes
 * an immediately closing close (writes empty accordingly). */
mvet_istatus_t
mvet_st_json_open_sequence(mvet_st_json_t *json, uint8_t open, uint8_t close, bool *empty);

/* Consumes the separator after a sequence element. close ends the
 * sequence (writes closed true); a comma continues, positioned on the
 * next element. */
mvet_istatus_t mvet_st_json_continue_sequence(mvet_st_json_t *json, uint8_t close, bool *closed);

/* True when the span's bytes equal literal[0..literal_length). Pure. */
bool mvet_st_json_span_is(const mvet_st_json_t *json,
                          mvet_span_t span,
                          const char *literal,
                          size_t literal_length);

#endif /* MVET_ST_JSON_H */
/* ---- src/st.h ---- */
/* st.h: internal vocabulary of the safetensors validator: carve-bound
 * constants with their proofs, the per-call pass context, and the pass
 * entry points. Format rules mirror the canonical implementation pinned
 * in tools/st-pin.env; policy deltas are marked at their producers.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#ifndef MVET_ST_H
#define MVET_ST_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


enum {
    MVET_ST_FRAME_BYTES = 8, /* the little-endian u64 header length */

    /* Arena carve bounds derive from the validated header length: k
     * entries of a kind cannot fit in fewer than k times these floor
     * byte counts, so length / divisor + 1 strictly exceeds any count
     * the walk can produce. The minimal spellings, with empty names:
     * root entry "__metadata__":{} is 17 bytes and a tensor root entry
     * is never smaller; metadata entry "":"" is 5 bytes; tensor entry
     * "":{"dtype":"F4","shape":[],"data_offsets":[0,0]} is 50 bytes. */
    MVET_ST_MIN_ROOT_ENTRY_BYTES = 17,
    MVET_ST_MIN_METADATA_ENTRY_BYTES = 5,
    MVET_ST_MIN_TENSOR_ENTRY_BYTES = 50
};

/* One tensor's declared data range, half open in data-region bytes.
 * Stored records satisfy begin <= end (validated before storage). */
typedef struct {
    uint64_t begin;
    uint64_t end;
} mvet_st_extent_t;

_Static_assert(sizeof(mvet_st_extent_t) == sizeof(uint64_t) * (size_t)MVET_ST_EXTENT_WORDS,
               "the public safetensors arena formula must match mvet_st_extent_t");
_Static_assert(sizeof(mvet_st_extent_t) % MVET_ARENA_ALIGN == 0u,
               "successive extent arrays must stay arena-aligned");
_Static_assert((uint64_t)MVET_MAX_ST_HEADER_BYTES <= (uint64_t)SIZE_MAX,
               "MVET_MAX_ST_HEADER_BYTES must fit size_t");
_Static_assert((uint64_t)MVET_MAX_ST_TENSORS < (uint64_t)SIZE_MAX,
               "MVET_MAX_ST_TENSORS must leave room for the metadata key");
_Static_assert((uint64_t)MVET_MAX_ST_METADATA_ENTRIES <= (uint64_t)SIZE_MAX,
               "MVET_MAX_ST_METADATA_ENTRIES must fit size_t");
_Static_assert((uint64_t)MVET_MAX_ST_NAME_BYTES <= (uint64_t)SIZE_MAX,
               "MVET_MAX_ST_NAME_BYTES must fit size_t");

/* Per-call pass context; lives on the entry point's stack. Invariants:
 * header names the frame-validated JSON region; data_region_bytes is
 * the file remainder past the header; each array is carved by the
 * frame pass to a bound derived from the header length and the caps,
 * and its count stays below that bound (the per-entry byte minimums
 * above are the proof); metadata_key_offset is meaningful only once
 * metadata_seen is true. */
typedef struct {
    mvet_cursor_t cursor;
    mvet_arena_t *arena;
    mvet_span_t header;
    uint64_t data_region_bytes;
    mvet_span_t *root_key_spans;
    size_t root_key_bound;
    size_t root_key_count;
    mvet_span_t *metadata_key_spans;
    size_t metadata_key_bound;
    size_t metadata_key_count;
    mvet_st_extent_t *extents;
    size_t extent_bound;
    size_t tensor_count;
    bool metadata_seen;
    size_t metadata_key_offset;
} mvet_st_t;

/* Validates the 8-byte frame against the header cap and the input
 * length, then carves the three work arrays. Violations: truncation
 * and the header-length cap. */
mvet_istatus_t mvet_st_frame_pass(mvet_st_t *context);

/* Walks the header JSON: root object, __metadata__ map, tensor
 * entries, then both duplicate-key checks. Violations: the 51x lexical
 * codes, the 52x caps, and the 53x tensor-entry codes. */
mvet_istatus_t mvet_st_header_pass(mvet_st_t *context);

/* Sorts the recorded extents by offsets and requires them to tile the
 * data region exactly. Violations: contiguity and data extent. */
mvet_istatus_t mvet_st_layout_pass(mvet_st_t *context);

/* Validates one tensor entry value and records its extent. json sits
 * on the value's first byte; both pointers are borrowed, non-NULL.
 * Violations: the 53x and 54x tensor codes. */
mvet_istatus_t mvet_st_tensor_entry(mvet_st_t *context, mvet_st_json_t *json);

#endif /* MVET_ST_H */
/* ---- src/arena.c ---- */
/* arena.c: owns the caller-provided fixed arena: public binding and the
 * internal aligned carve.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


enum {
    MVET_ARENA_ALIGNMENT_MASK = MVET_ARENA_ALIGN - 1
};

/* A successful carve plan. allocation is NULL only for a zero-byte carve;
 * used_after_bytes is the committed arena high-water mark. */
typedef struct {
    void *allocation;
    size_t used_after_bytes;
} mvet_arena_allocation_plan_t;

/* True for a valid binding request. Both pointers are borrowed; either may be NULL. Pure. */
static bool
mvet_arena_is_binding_valid(const mvet_arena_t *arena, const void *memory, size_t capacity);

/* Stores one validated binding. arena is a non-NULL borrowed context; memory is borrowed,
 * possibly NULL only at zero capacity. Infallible. */
static void mvet_arena_store_binding(mvet_arena_t *arena, void *memory, size_t capacity);

/* Builds the next aligned carve plan without changing arena. arena is a non-NULL borrowed
 * context; output_plan is a non-NULL caller-owned output, untouched on failure. Fails with
 * MVET_I_ERR_ARENA when the carve cannot fit. */
static mvet_istatus_t mvet_arena_plan_allocation(const mvet_arena_t *arena,
                                                 mvet_arena_allocation_plan_t *output_plan,
                                                 size_t byte_count);

/* Finds the aligned offset where a non-empty carve fits. arena is a non-NULL borrowed
 * context; output_offset is a non-NULL caller-owned output, untouched on failure. On
 * success, offset + byte_count <= capacity. Fails with MVET_I_ERR_ARENA when the carve
 * cannot fit. */
static mvet_istatus_t
mvet_arena_find_offset(const mvet_arena_t *arena, size_t *output_offset, size_t byte_count);

/* Computes padding before the next non-empty carve. arena is a non-NULL borrowed context. Pure. */
static size_t mvet_arena_get_padding(const mvet_arena_t *arena);

/* Applies one successful carve plan. arena is a non-NULL borrowed context; allocation is a
 * non-NULL caller-owned output. plan came from mvet_arena_plan_allocation. Infallible. */
static void mvet_arena_commit_allocation(mvet_arena_t *arena,
                                         void **allocation,
                                         mvet_arena_allocation_plan_t plan);

mvet_status_t mvet_arena_bind(mvet_arena_t *arena, void *memory, size_t capacity)
{
    if (!mvet_arena_is_binding_valid(arena, memory, capacity))
        return MVET_ERR_ARG;

    mvet_arena_store_binding(arena, memory, capacity);
    return MVET_OK;
}

mvet_istatus_t mvet_arena_allocate(mvet_arena_t *arena, void **allocation, size_t byte_count)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(allocation != NULL);
    MVET_ASSERT(arena->used <= arena->capacity);

    mvet_arena_allocation_plan_t plan = {0};
    mvet_istatus_t status = mvet_arena_plan_allocation(arena, &plan, byte_count);
    if (status != MVET_I_OK)
        return status;

    mvet_arena_commit_allocation(arena, allocation, plan);
    return MVET_I_OK;
}

static bool
mvet_arena_is_binding_valid(const mvet_arena_t *arena, const void *memory, size_t capacity)
{
    if (arena == NULL)
        return false;
    if (memory == NULL && capacity != 0)
        return false;
    return true;
}

static void mvet_arena_store_binding(mvet_arena_t *arena, void *memory, size_t capacity)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(memory != NULL || capacity == 0);

    arena->base = (uint8_t *)memory;
    arena->capacity = capacity;
    arena->used = 0;
}

static mvet_istatus_t mvet_arena_plan_allocation(const mvet_arena_t *arena,
                                                 mvet_arena_allocation_plan_t *output_plan,
                                                 size_t byte_count)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(output_plan != NULL);
    MVET_ASSERT(arena->used <= arena->capacity);

    if (byte_count == 0) {
        *output_plan = (mvet_arena_allocation_plan_t){
            .allocation = NULL,
            .used_after_bytes = arena->used,
        };
        return MVET_I_OK;
    }

    size_t offset_bytes = 0;
    MVET_TRY(mvet_arena_find_offset(arena, &offset_bytes, byte_count));

    /* Non-wrapping raw +: mvet_arena_find_offset guarantees
     * offset_bytes + byte_count <= arena->capacity on success. */
    MVET_ASSERT(arena->base != NULL);
    *output_plan = (mvet_arena_allocation_plan_t){
        .allocation = (void *)(arena->base + offset_bytes),
        .used_after_bytes = offset_bytes + byte_count,
    };
    return MVET_I_OK;
}

static mvet_istatus_t
mvet_arena_find_offset(const mvet_arena_t *arena, size_t *output_offset, size_t byte_count)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(output_offset != NULL);
    MVET_ASSERT(byte_count > 0);
    MVET_ASSERT(arena->used <= arena->capacity);

    size_t padding_bytes = mvet_arena_get_padding(arena);
    size_t free_bytes = arena->capacity - arena->used;
    if (padding_bytes > free_bytes)
        return MVET_I_ERR_ARENA;

    size_t usable_bytes = free_bytes - padding_bytes;
    if (byte_count > usable_bytes)
        return MVET_I_ERR_ARENA;

    *output_offset = arena->used + padding_bytes;
    return MVET_I_OK;
}

static size_t mvet_arena_get_padding(const mvet_arena_t *arena)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(arena->used <= arena->capacity);

    if (arena->base == NULL)
        return 0;

    uintptr_t address = (uintptr_t)arena->base + arena->used;
    return (size_t)(-address & (uintptr_t)MVET_ARENA_ALIGNMENT_MASK);
}

static void mvet_arena_commit_allocation(mvet_arena_t *arena,
                                         void **allocation,
                                         mvet_arena_allocation_plan_t plan)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(allocation != NULL);
    MVET_ASSERT(plan.used_after_bytes >= arena->used);
    MVET_ASSERT(plan.used_after_bytes <= arena->capacity);

    *allocation = plan.allocation;
    arena->used = plan.used_after_bytes;
    MVET_ASSERT(arena->used <= arena->capacity);
}
/* ---- src/checked.c ---- */
/* checked.c: owns overflow-checked arithmetic on file-derived integers.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


/* Returns the padding required for value. Alignment must be a nonzero power of two. Pure. */
static uint64_t mvet_checked_alignment_padding(uint64_t value, uint64_t alignment);

bool mvet_checked_add_u64(uint64_t *result, uint64_t left, uint64_t right)
{
    MVET_ASSERT(result != NULL);

    if (right > UINT64_MAX - left)
        return false;
    *result = left + right;
    MVET_ASSERT(*result >= left);
    return true;
}

bool mvet_checked_mul_u64(uint64_t *result, uint64_t left, uint64_t right)
{
    MVET_ASSERT(result != NULL);

    if (left != 0 && right > UINT64_MAX / left)
        return false;
    *result = left * right;
    MVET_ASSERT(left == 0 || *result / left == right);
    return true;
}

bool mvet_checked_align_up_u64(uint64_t *result, uint64_t value, uint64_t alignment)
{
    MVET_ASSERT(result != NULL);
    MVET_ASSERT(alignment != 0);
    MVET_ASSERT((alignment & (alignment - 1u)) == 0);

    uint64_t padding = mvet_checked_alignment_padding(value, alignment);
    return mvet_checked_add_u64(result, value, padding);
}

bool mvet_checked_u64_to_size(size_t *result, uint64_t value)
{
    MVET_ASSERT(result != NULL);

/* Guarded so 64-bit builds do not see an always-false comparison. */
#if SIZE_MAX < UINT64_MAX
    if (value > (uint64_t)SIZE_MAX)
        return false;
#endif
    *result = (size_t)value;
    MVET_ASSERT((uint64_t)*result == value);
    return true;
}

bool mvet_checked_in_range_u64(uint64_t value, uint64_t minimum, uint64_t maximum)
{
    MVET_ASSERT(minimum <= maximum);

    return value >= minimum && value <= maximum;
}

static uint64_t mvet_checked_alignment_padding(uint64_t value, uint64_t alignment)
{
    MVET_ASSERT(alignment != 0);
    MVET_ASSERT((alignment & (alignment - 1u)) == 0);

    uint64_t remainder = value & (alignment - 1u);
    if (remainder == 0)
        return 0;
    return alignment - remainder;
}
/* ---- src/cursor.c ---- */
/* cursor.c: owns bounded input reads plus the sole truncation violation producer.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stddef.h>
#include <stdint.h>


enum {
    MVET_CURSOR_U8_BYTES = 1,
    MVET_CURSOR_U32_BYTES = 4,
    MVET_CURSOR_U64_BYTES = 8,
    MVET_CURSOR_BYTE_BITS = 8
};

/* Reads one byte_count-wide scalar through borrowed non-NULL cursor. result is a borrowed non-NULL
 * destination. Returns MVET_I_HALT for truncation; result stays untouched then. */
static mvet_istatus_t
mvet_cursor_read_little_endian(mvet_cursor_t *cursor, uint64_t *result, size_t byte_count);

/* Decodes one bounded span through borrowed non-NULL cursor. Pure. span contains one to eight
 * bytes. */
static uint64_t mvet_cursor_decode_little_endian(const mvet_cursor_t *cursor, mvet_span_t span);

/* Narrows a decoded scalar proven to fit uint8_t. Pure. */
static uint8_t mvet_cursor_narrow_u8(uint64_t value);

/* Narrows a decoded scalar proven to fit uint32_t. Pure. */
static uint32_t mvet_cursor_narrow_u32(uint64_t value);

/* Records the next length bytes in borrowed non-NULL span. cursor is borrowed non-NULL state. */
static void mvet_cursor_record_span(const mvet_cursor_t *cursor, mvet_span_t *span, size_t length);

/* Advances borrowed non-NULL cursor across a previously required length. */
static void mvet_cursor_advance(mvet_cursor_t *cursor, size_t length);

void mvet_cursor_bind(mvet_cursor_t *cursor,
                      mvet_report_t *report,
                      const uint8_t *buffer,
                      size_t length)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(buffer != NULL || length == 0);

    cursor->buffer = buffer;
    cursor->length = length;
    cursor->offset = 0;
    cursor->report = report;
}

mvet_istatus_t mvet_cursor_require(mvet_cursor_t *cursor, size_t length)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(cursor->report != NULL);
    MVET_ASSERT(cursor->offset <= cursor->length);

    size_t remaining = cursor->length - cursor->offset;
    if (length <= remaining)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_TRUNCATED, (uint64_t)cursor->offset, (uint64_t)length, (uint64_t)remaining);
    return mvet_violation(cursor->report, issue);
}

mvet_istatus_t mvet_cursor_read_u8(mvet_cursor_t *cursor, uint8_t *value)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(value != NULL);

    uint64_t wide_value = 0;
    MVET_TRY(mvet_cursor_read_little_endian(cursor, &wide_value, MVET_CURSOR_U8_BYTES));
    *value = mvet_cursor_narrow_u8(wide_value);
    return MVET_I_OK;
}

mvet_istatus_t mvet_cursor_read_u32(mvet_cursor_t *cursor, uint32_t *value)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(value != NULL);

    uint64_t wide_value = 0;
    MVET_TRY(mvet_cursor_read_little_endian(cursor, &wide_value, MVET_CURSOR_U32_BYTES));
    *value = mvet_cursor_narrow_u32(wide_value);
    return MVET_I_OK;
}

mvet_istatus_t mvet_cursor_read_u64(mvet_cursor_t *cursor, uint64_t *value)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(value != NULL);

    return mvet_cursor_read_little_endian(cursor, value, MVET_CURSOR_U64_BYTES);
}

mvet_istatus_t mvet_cursor_take_span(mvet_cursor_t *cursor, mvet_span_t *span, size_t length)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(span != NULL);

    MVET_TRY(mvet_cursor_require(cursor, length));
    mvet_cursor_record_span(cursor, span, length);
    mvet_cursor_advance(cursor, length);
    return MVET_I_OK;
}

mvet_istatus_t mvet_cursor_skip(mvet_cursor_t *cursor, size_t length)
{
    MVET_ASSERT(cursor != NULL);

    MVET_TRY(mvet_cursor_require(cursor, length));
    mvet_cursor_advance(cursor, length);
    return MVET_I_OK;
}

const uint8_t *mvet_cursor_get_span_pointer(const mvet_cursor_t *cursor, mvet_span_t span)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(span.offset <= cursor->length);
    MVET_ASSERT(span.length <= cursor->length - span.offset);

    if (cursor->buffer == NULL)
        return NULL;
    return cursor->buffer + span.offset;
}

static mvet_istatus_t
mvet_cursor_read_little_endian(mvet_cursor_t *cursor, uint64_t *result, size_t byte_count)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(result != NULL);
    MVET_ASSERT(byte_count >= MVET_CURSOR_U8_BYTES);
    MVET_ASSERT(byte_count <= MVET_CURSOR_U64_BYTES);

    mvet_span_t bytes = {0};
    MVET_TRY(mvet_cursor_take_span(cursor, &bytes, byte_count));
    *result = mvet_cursor_decode_little_endian(cursor, bytes);
    return MVET_I_OK;
}

static uint64_t mvet_cursor_decode_little_endian(const mvet_cursor_t *cursor, mvet_span_t span)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(span.length >= MVET_CURSOR_U8_BYTES);
    MVET_ASSERT(span.length <= MVET_CURSOR_U64_BYTES);

    const uint8_t *bytes = mvet_cursor_get_span_pointer(cursor, span);
    MVET_ASSERT(bytes != NULL);

    uint64_t value = 0;
    for (size_t byte_index = 0; byte_index < MVET_CURSOR_U64_BYTES; byte_index++) {
        if (byte_index >= span.length)
            break;
        size_t shift_bits = MVET_CURSOR_BYTE_BITS * byte_index;
        value |= (uint64_t)bytes[byte_index] << shift_bits;
    }
    return value;
}

static uint8_t mvet_cursor_narrow_u8(uint64_t value)
{
    MVET_ASSERT(value <= UINT8_MAX);

    return (uint8_t)value;
}

static uint32_t mvet_cursor_narrow_u32(uint64_t value)
{
    MVET_ASSERT(value <= UINT32_MAX);

    return (uint32_t)value;
}

static void mvet_cursor_record_span(const mvet_cursor_t *cursor, mvet_span_t *span, size_t length)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(span != NULL);
    MVET_ASSERT(cursor->offset <= cursor->length);
    MVET_ASSERT(length <= cursor->length - cursor->offset);

    span->offset = cursor->offset;
    span->length = length;
}

static void mvet_cursor_advance(mvet_cursor_t *cursor, size_t length)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(cursor->offset <= cursor->length);
    MVET_ASSERT(length <= cursor->length - cursor->offset);

    /* Every byte the parse consumes is charged once here: the cursor is
     * monotone, so this is the whole payload-traversal work term. */
    MVET_WORK_ADD(length + 1u);
    cursor->offset += length;
    MVET_ASSERT(cursor->offset <= cursor->length);
}
/* ---- src/gguf.c ---- */
/* gguf.c: public entry point for GGUF verification; owns argument
 * validation, pass sequencing, and the mapping from internal pass status
 * to API status.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stddef.h>
#include <stdint.h>


/* One validated whole-buffer input view. */
typedef struct {
    const uint8_t *buffer;
    size_t length;
} mvet_gguf_input_t;

/* Rejects a NULL report. report is caller-owned; NULL is accepted for validation.
 * Fails with MVET_ERR_ARG. */
static mvet_status_t mvet_gguf_validate_report(const mvet_report_t *report);

/* Validates the public arena/input contract. arena is borrowed; NULL is accepted for
 * validation. buffer is borrowed; NULL requires zero length. Fails with MVET_ERR_ARG. */
static mvet_status_t
mvet_gguf_validate_input(const mvet_arena_t *arena, const void *buffer, size_t length);

/* Resets the arena high-water mark. arena is non-NULL caller-owned storage. Infallible. */
static void mvet_gguf_reset_arena(mvet_arena_t *arena);

/* Returns a validated byte view. buffer is borrowed; NULL is permitted only at zero length.
 * Infallible. */
static mvet_gguf_input_t mvet_gguf_make_input(const void *buffer, size_t length);

/* Runs the three validation passes in file order. report is non-NULL caller-owned state.
 * arena is non-NULL caller-owned state. input borrows the whole buffer. */
static mvet_istatus_t
mvet_gguf_run_passes(mvet_report_t *report, mvet_arena_t *arena, mvet_gguf_input_t input);

/* Returns a fresh pass context. arena is non-NULL borrowed state. Infallible. */
static mvet_gguf_t mvet_gguf_make_context(mvet_arena_t *arena);

/* Completes the public result for status. report is non-NULL caller-owned state. Infallible. */
static mvet_status_t mvet_gguf_map_status(mvet_report_t *report, mvet_istatus_t status);

/* Marks a fail-closed report as structurally accepted. report is non-NULL caller-owned state.
 * Infallible. This is the only writer of MVET_VERDICT_ACCEPT. */
static void mvet_gguf_accept_report(mvet_report_t *report);

/* Returns the public API error for an internal API failure. Pure. */
static mvet_status_t mvet_gguf_map_error(mvet_istatus_t status);

mvet_status_t
mvet_gguf_verify(mvet_report_t *report, mvet_arena_t *arena, const void *buffer, size_t length)
{
    mvet_status_t public_status = mvet_gguf_validate_report(report);
    if (public_status != MVET_OK)
        return public_status;

    mvet_report_clear(report);
    public_status = mvet_gguf_validate_input(arena, buffer, length);
    if (public_status != MVET_OK)
        return public_status;

    mvet_gguf_reset_arena(arena);
    mvet_gguf_input_t input = mvet_gguf_make_input(buffer, length);

    mvet_istatus_t status = mvet_gguf_run_passes(report, arena, input);
    return mvet_gguf_map_status(report, status);
}

static mvet_status_t mvet_gguf_validate_report(const mvet_report_t *report)
{
    if (report == NULL)
        return MVET_ERR_ARG;
    return MVET_OK;
}

static mvet_status_t
mvet_gguf_validate_input(const mvet_arena_t *arena, const void *buffer, size_t length)
{
    if (arena == NULL)
        return MVET_ERR_ARG;
    if (buffer == NULL && length != 0)
        return MVET_ERR_ARG;
    if (arena->base == NULL && arena->capacity != 0)
        return MVET_ERR_ARG;
    return MVET_OK;
}

static void mvet_gguf_reset_arena(mvet_arena_t *arena)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(arena->base != NULL || arena->capacity == 0);

    arena->used = 0;
    MVET_ASSERT(arena->used <= arena->capacity);
}

static mvet_gguf_input_t mvet_gguf_make_input(const void *buffer, size_t length)
{
    MVET_ASSERT(buffer != NULL || length == 0);

    return (mvet_gguf_input_t){
        .buffer = (const uint8_t *)buffer,
        .length = length,
    };
}

static mvet_istatus_t
mvet_gguf_run_passes(mvet_report_t *report, mvet_arena_t *arena, mvet_gguf_input_t input)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(arena != NULL);

    mvet_gguf_t context = mvet_gguf_make_context(arena);
    mvet_cursor_t *cursor = &context.cursor;
    mvet_cursor_bind(cursor, report, input.buffer, input.length);

    mvet_istatus_t status = mvet_gguf_header_pass(&context);
    if (status != MVET_I_OK)
        return status;

    status = mvet_gguf_kv_pass(&context);
    if (status != MVET_I_OK)
        return status;
    return mvet_gguf_tensor_pass(&context);
}

static mvet_gguf_t mvet_gguf_make_context(mvet_arena_t *arena)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(arena->used == 0);

    mvet_gguf_t context = {
        .arena = arena,
        .alignment = MVET_GGUF_DEFAULT_ALIGNMENT,
    };
    MVET_ASSERT(context.arena == arena);
    MVET_ASSERT(context.alignment == MVET_GGUF_DEFAULT_ALIGNMENT);
    return context;
}

static mvet_status_t mvet_gguf_map_status(mvet_report_t *report, mvet_istatus_t status)
{
    MVET_ASSERT(report != NULL);

    if (status == MVET_I_OK) {
        mvet_gguf_accept_report(report);
        return MVET_OK;
    }
    if (status == MVET_I_HALT)
        return MVET_OK; /* report already carries the violation */

    mvet_report_clear(report);
    return mvet_gguf_map_error(status);
}

static void mvet_gguf_accept_report(mvet_report_t *report)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(report->verdict == MVET_VERDICT_REJECT);
    MVET_ASSERT(report->violation == MVET_V_NONE);

    report->verdict = MVET_VERDICT_ACCEPT;
    MVET_ASSERT(report->verdict == MVET_VERDICT_ACCEPT);
}

static mvet_status_t mvet_gguf_map_error(mvet_istatus_t status)
{
    MVET_ASSERT(status != MVET_I_OK);
    MVET_ASSERT(status != MVET_I_HALT);

    if (status == MVET_I_ERR_ARENA)
        return MVET_ERR_ARENA;
    return MVET_ERR_ARG;
}
/* ---- src/gguf_header.c ---- */
/* gguf_header.c: owns GGUF header parsing plus bounded span-index carving.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


/* One decoded header count paired with its cap plus violation code.
 * maximum_count always fits size_t. */
typedef struct {
    size_t field_offset;
    uint64_t declared_count;
    uint64_t maximum_count;
    uint32_t violation_code;
} mvet_gguf_count_field_t;

/* Parses every fixed field through borrowed non-NULL context. Returns the first read or rule
 * failure. This routine acquires no storage. */
static mvet_istatus_t mvet_gguf_parse_header_fields(mvet_gguf_t *context);

/* Parses the magic field through borrowed non-NULL context. Returns MVET_I_HALT for truncation
 * or mismatch. */
static mvet_istatus_t mvet_gguf_read_magic(mvet_gguf_t *context);

/* Checks one decoded magic field. report is borrowed non-NULL storage. Returns MVET_I_HALT for a
 * mismatch. */
static mvet_istatus_t
mvet_gguf_check_magic(mvet_report_t *report, size_t field_offset, uint32_t magic);

/* Parses the version field through borrowed non-NULL context. Returns MVET_I_HALT for truncation
 * or an invalid version. */
static mvet_istatus_t mvet_gguf_read_version(mvet_gguf_t *context);

/* Applies version rules in diagnostic order. report is borrowed non-NULL storage. Returns the
 * first version-rule failure. */
static mvet_istatus_t
mvet_gguf_check_version(mvet_report_t *report, size_t field_offset, uint32_t version);

/* Rejects the legacy wire version. report is borrowed non-NULL storage. Returns MVET_I_HALT only
 * for that version. */
static mvet_istatus_t
mvet_gguf_check_legacy_version(mvet_report_t *report, size_t field_offset, uint32_t version);

/* Rejects a byte-swapped version marker. report is borrowed non-NULL storage. Returns MVET_I_HALT
 * only for that marker. */
static mvet_istatus_t
mvet_gguf_check_endian_version(mvet_report_t *report, size_t field_offset, uint32_t version);

/* Rejects a version outside the supported interval. report is borrowed non-NULL storage. Returns
 * MVET_I_HALT only outside that interval. */
static mvet_istatus_t
mvet_gguf_check_supported_version(mvet_report_t *report, size_t field_offset, uint32_t version);

/* Parses one capped count through borrowed non-NULL context. output_count is a borrowed non-NULL
 * destination. Returns MVET_I_HALT for truncation or a cap violation. */
static mvet_istatus_t mvet_gguf_read_count(mvet_gguf_t *context,
                                           size_t *output_count,
                                           uint64_t maximum_count,
                                           uint32_t violation_code);

/* Checks one decoded count field. report is borrowed non-NULL storage. Returns MVET_I_HALT only
 * when the declared count exceeds its cap. */
static mvet_istatus_t mvet_gguf_check_count(mvet_report_t *report, mvet_gguf_count_field_t field);

/* Stores one cap-validated count in borrowed non-NULL output_count. */
static void mvet_gguf_record_count(size_t *output_count, mvet_gguf_count_field_t field);

/* Carves both span indexes through borrowed non-NULL context. Returns MVET_I_ERR_ARENA when caller
 * storage cannot hold either index. */
static mvet_istatus_t mvet_gguf_allocate_indexes(mvet_gguf_t *context);

/* Carves one count-sized span index through borrowed non-NULL context. output_spans is a borrowed
 * non-NULL destination. Returns MVET_I_ERR_ARENA when caller storage is insufficient. */
static mvet_istatus_t
mvet_gguf_allocate_index(mvet_gguf_t *context, mvet_span_t **output_spans, size_t count);

/* Calculates one span-index size in borrowed non-NULL output_bytes. Returns MVET_I_ERR_ARENA if
 * size_t cannot hold the result. */
static mvet_istatus_t mvet_gguf_calculate_index_bytes(size_t *output_bytes, size_t count);

mvet_istatus_t mvet_gguf_header_pass(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->arena != NULL);

    mvet_istatus_t status = mvet_gguf_parse_header_fields(context);
    if (status != MVET_I_OK)
        return status;
    return mvet_gguf_allocate_indexes(context);
}

static mvet_istatus_t mvet_gguf_parse_header_fields(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->cursor.report != NULL);

    MVET_TRY(mvet_gguf_read_magic(context));
    MVET_TRY(mvet_gguf_read_version(context));
    MVET_TRY(mvet_gguf_read_count(
        context, &context->tensor_count, MVET_MAX_TENSORS, MVET_V_TENSOR_COUNT_RANGE));
    return mvet_gguf_read_count(
        context, &context->kv_count, MVET_MAX_KV_COUNT, MVET_V_KV_COUNT_RANGE);
}

static mvet_istatus_t mvet_gguf_read_magic(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->cursor.report != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    size_t field_offset = cursor->offset;
    uint32_t magic = 0;
    MVET_TRY(mvet_cursor_read_u32(cursor, &magic));
    return mvet_gguf_check_magic(cursor->report, field_offset, magic);
}

static mvet_istatus_t
mvet_gguf_check_magic(mvet_report_t *report, size_t field_offset, uint32_t magic)
{
    MVET_ASSERT(report != NULL);

    if (magic == MVET_GGUF_MAGIC_LE)
        return MVET_I_OK;

    mvet_issue_t issue =
        mvet_issue_make(MVET_V_MAGIC, (uint64_t)field_offset, magic, MVET_GGUF_MAGIC_LE);
    return mvet_violation(report, issue);
}

static mvet_istatus_t mvet_gguf_read_version(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->cursor.report != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    size_t field_offset = cursor->offset;
    uint32_t version = 0;
    MVET_TRY(mvet_cursor_read_u32(cursor, &version));
    return mvet_gguf_check_version(cursor->report, field_offset, version);
}

static mvet_istatus_t
mvet_gguf_check_version(mvet_report_t *report, size_t field_offset, uint32_t version)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(MVET_GGUF_VERSION_MIN <= MVET_GGUF_VERSION_MAX);

    MVET_TRY(mvet_gguf_check_legacy_version(report, field_offset, version));
    MVET_TRY(mvet_gguf_check_endian_version(report, field_offset, version));
    return mvet_gguf_check_supported_version(report, field_offset, version);
}

static mvet_istatus_t
mvet_gguf_check_legacy_version(mvet_report_t *report, size_t field_offset, uint32_t version)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(MVET_GGUF_VERSION_LEGACY < MVET_GGUF_VERSION_MIN);

    if (version != MVET_GGUF_VERSION_LEGACY)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(MVET_V_VERSION_LEGACY, (uint64_t)field_offset, version, 0);
    return mvet_violation(report, issue);
}

static mvet_istatus_t
mvet_gguf_check_endian_version(mvet_report_t *report, size_t field_offset, uint32_t version)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(MVET_GGUF_ENDIAN_MASK != 0);

    bool is_swapped = version != 0 && (version & MVET_GGUF_ENDIAN_MASK) == 0;
    if (!is_swapped)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(MVET_V_VERSION_ENDIAN, (uint64_t)field_offset, version, 0);
    return mvet_violation(report, issue);
}

static mvet_istatus_t
mvet_gguf_check_supported_version(mvet_report_t *report, size_t field_offset, uint32_t version)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(MVET_GGUF_VERSION_MIN <= MVET_GGUF_VERSION_MAX);

    bool is_supported =
        mvet_checked_in_range_u64(version, MVET_GGUF_VERSION_MIN, MVET_GGUF_VERSION_MAX);
    if (is_supported)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_VERSION_UNSUPPORTED, (uint64_t)field_offset, version, MVET_GGUF_VERSION_MAX);
    return mvet_violation(report, issue);
}

static mvet_istatus_t mvet_gguf_read_count(mvet_gguf_t *context,
                                           size_t *output_count,
                                           uint64_t maximum_count,
                                           uint32_t violation_code)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(output_count != NULL);
    MVET_ASSERT(maximum_count == MVET_MAX_TENSORS || maximum_count == MVET_MAX_KV_COUNT);
    MVET_ASSERT(violation_code != MVET_V_NONE);

    mvet_cursor_t *cursor = &context->cursor;
    mvet_gguf_count_field_t field = {
        .field_offset = cursor->offset,
        .declared_count = 0,
        .maximum_count = maximum_count,
        .violation_code = violation_code,
    };
    MVET_TRY(mvet_cursor_read_u64(cursor, &field.declared_count));
    MVET_TRY(mvet_gguf_check_count(cursor->report, field));
    mvet_gguf_record_count(output_count, field);
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_check_count(mvet_report_t *report, mvet_gguf_count_field_t field)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(field.violation_code != MVET_V_NONE);

    if (field.declared_count <= field.maximum_count)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(field.violation_code,
                                         (uint64_t)field.field_offset,
                                         field.declared_count,
                                         field.maximum_count);
    return mvet_violation(report, issue);
}

static void mvet_gguf_record_count(size_t *output_count, mvet_gguf_count_field_t field)
{
    MVET_ASSERT(output_count != NULL);
    MVET_ASSERT(field.declared_count <= field.maximum_count);
    MVET_ASSERT((uint64_t)(size_t)field.declared_count == field.declared_count);

    *output_count = (size_t)field.declared_count;
}

static mvet_istatus_t mvet_gguf_allocate_indexes(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->arena != NULL);
    MVET_ASSERT(context->key_spans == NULL);
    MVET_ASSERT(context->name_spans == NULL);

    mvet_istatus_t status =
        mvet_gguf_allocate_index(context, &context->key_spans, context->kv_count);
    if (status != MVET_I_OK)
        return status;
    return mvet_gguf_allocate_index(context, &context->name_spans, context->tensor_count);
}

static mvet_istatus_t
mvet_gguf_allocate_index(mvet_gguf_t *context, mvet_span_t **output_spans, size_t count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->arena != NULL);
    MVET_ASSERT(output_spans != NULL);
    MVET_ASSERT(*output_spans == NULL);
    MVET_ASSERT(count <= (MVET_MAX_KV_COUNT > MVET_MAX_TENSORS ? (size_t)MVET_MAX_KV_COUNT
                                                               : (size_t)MVET_MAX_TENSORS));

    size_t allocation_bytes = 0;
    mvet_istatus_t status = mvet_gguf_calculate_index_bytes(&allocation_bytes, count);
    if (status != MVET_I_OK)
        return status;

    void *memory = NULL;
    status = mvet_arena_allocate(context->arena, &memory, allocation_bytes);
    if (status != MVET_I_OK)
        return status;

    *output_spans = (mvet_span_t *)memory;
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_calculate_index_bytes(size_t *output_bytes, size_t count)
{
    MVET_ASSERT(output_bytes != NULL);

    uint64_t wide_bytes = 0;
    bool product_fits =
        mvet_checked_mul_u64(&wide_bytes, (uint64_t)count, (uint64_t)sizeof(mvet_span_t));
    if (!product_fits)
        return MVET_I_ERR_ARENA;
    if (!mvet_checked_u64_to_size(output_bytes, wide_bytes))
        return MVET_I_ERR_ARENA;
    return MVET_I_OK;
}
/* ---- src/gguf_kv.c ---- */
/* gguf_kv.c: owns bounded GGUF metadata decoding.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


enum {
    MVET_GGUF_KV_BYTE_BYTES = sizeof(uint8_t),
    MVET_GGUF_KV_UINT16_BYTES = sizeof(uint16_t),
    MVET_GGUF_KV_UINT32_BYTES = sizeof(uint32_t),
    MVET_GGUF_KV_UINT64_BYTES = sizeof(uint64_t),
    MVET_GGUF_KV_TAG_BYTES = MVET_GGUF_KV_UINT32_BYTES,
    MVET_GGUF_KV_LENGTH_BYTES = MVET_GGUF_KV_UINT64_BYTES,
    MVET_GGUF_KV_ARRAY_HEADER_BYTES = MVET_GGUF_KV_TAG_BYTES + MVET_GGUF_KV_LENGTH_BYTES
};

#define MVET_GGUF_KV_ALIGNMENT_KEY "general.alignment"

/* One decoded metadata key plus its validated outer tag. */
typedef struct {
    mvet_span_t key;
    size_t tag_offset;
    uint32_t tag;
} mvet_gguf_kv_entry_t;

/* One decoded array header awaiting payload dispatch. */
typedef struct {
    size_t tag_offset;
    size_t count_offset;
    uint32_t tag;
    uint64_t count;
} mvet_gguf_kv_array_t;

/* Alignment remains pending until duplicate-key validation succeeds. */
typedef struct {
    bool present;
    size_t value_offset;
    uint32_t value;
} mvet_gguf_kv_alignment_t;

/* A metadata-budget update proven to fit the configured cap. */
typedef struct {
    uint64_t total_bytes;
} mvet_gguf_kv_charge_t;

/* Fixed-width element sizes. Non-fixed tags stay zero. */
static const uint8_t mvet_gguf_kv_element_bytes[MVET_GGUF_TAG_MAX + 1] = {
    [MVET_GGUF_TAG_UINT8] = MVET_GGUF_KV_BYTE_BYTES,
    [MVET_GGUF_TAG_INT8] = MVET_GGUF_KV_BYTE_BYTES,
    [MVET_GGUF_TAG_UINT16] = MVET_GGUF_KV_UINT16_BYTES,
    [MVET_GGUF_TAG_INT16] = MVET_GGUF_KV_UINT16_BYTES,
    [MVET_GGUF_TAG_UINT32] = MVET_GGUF_KV_UINT32_BYTES,
    [MVET_GGUF_TAG_INT32] = MVET_GGUF_KV_UINT32_BYTES,
    [MVET_GGUF_TAG_FLOAT32] = MVET_GGUF_KV_UINT32_BYTES,
    [MVET_GGUF_TAG_UINT64] = MVET_GGUF_KV_UINT64_BYTES,
    [MVET_GGUF_TAG_INT64] = MVET_GGUF_KV_UINT64_BYTES,
    [MVET_GGUF_TAG_FLOAT64] = MVET_GGUF_KV_UINT64_BYTES,
};

/* Parses one entry into pass state. Both pointers are borrowed, non-NULL.
 * Propagates parser status. */
static mvet_istatus_t mvet_gguf_kv_read_entry(mvet_gguf_t *context,
                                              mvet_gguf_kv_alignment_t *alignment,
                                              size_t entry_index);

/* Parses one nonempty key into output_key. Both pointers are borrowed,
 * non-NULL. Propagates string status; halts for an empty key. */
static mvet_istatus_t mvet_gguf_kv_read_key(mvet_gguf_t *context, mvet_span_t *output_key);

/* Parses one role-governed string into output_span. Both pointers are
 * borrowed, non-NULL. Propagates string or budget status. */
static mvet_istatus_t mvet_gguf_kv_read_string(mvet_gguf_t *context,
                                               mvet_span_t *output_span,
                                               mvet_gguf_string_role_t role);

/* Charges one string's encoded size. context is borrowed, non-NULL.
 * Halts when the metadata budget is exceeded. */
static mvet_istatus_t mvet_gguf_kv_charge_string(mvet_gguf_t *context,
                                                 mvet_gguf_string_header_t header);

/* Computes one string's encoded size, saturated at UINT64_MAX. Pure. */
static uint64_t mvet_gguf_kv_get_string_bytes(mvet_gguf_string_header_t header);

/* Charges byte_count to the metadata budget. context is borrowed, non-NULL.
 * Halts when the metadata budget is exceeded. */
static mvet_istatus_t
mvet_gguf_kv_charge_bytes(mvet_gguf_t *context, size_t field_offset, uint64_t byte_count);

/* Plans one metadata-budget update. Both pointers are borrowed, non-NULL.
 * Halts when the update cannot fit. */
static mvet_istatus_t mvet_gguf_kv_check_charge(mvet_gguf_t *context,
                                                mvet_gguf_kv_charge_t *output_charge,
                                                size_t field_offset,
                                                uint64_t byte_count);

/* Commits a proven metadata-budget update. context is borrowed, non-NULL.
 * No failure. */
static void mvet_gguf_kv_commit_charge(mvet_gguf_t *context, mvet_gguf_kv_charge_t charge);

/* Enforces the nonempty-key policy. context is borrowed, non-NULL.
 * Halts for an empty span. */
static mvet_istatus_t
mvet_gguf_kv_check_key(mvet_gguf_t *context, size_t field_offset, mvet_span_t key);

/* Stores a proven key span. context is borrowed, non-NULL. No failure. */
static void mvet_gguf_kv_index_key(mvet_gguf_t *context, size_t entry_index, mvet_span_t key);

/* Parses one valid outer tag into entry. Both pointers are borrowed,
 * non-NULL. Propagates cursor, range, or budget status. */
static mvet_istatus_t mvet_gguf_kv_read_tag(mvet_gguf_t *context, mvet_gguf_kv_entry_t *entry);

/* Enforces the outer-tag range. context is borrowed, non-NULL.
 * Halts for an unknown tag. */
static mvet_istatus_t
mvet_gguf_kv_check_tag(mvet_gguf_t *context, size_t field_offset, uint32_t tag);

/* Dispatches one entry value. Both pointers are borrowed, non-NULL.
 * Propagates value-parser status. */
static mvet_istatus_t mvet_gguf_kv_read_entry_value(mvet_gguf_t *context,
                                                    mvet_gguf_kv_alignment_t *alignment,
                                                    mvet_gguf_kv_entry_t entry);

/* True when key names the reserved alignment entry. context is borrowed,
 * non-NULL. Pure. */
static bool mvet_gguf_kv_is_alignment_key(const mvet_gguf_t *context, mvet_span_t key);

/* Parses one pending alignment entry. Both pointers are borrowed, non-NULL.
 * Propagates value-parser status. */
static mvet_istatus_t mvet_gguf_kv_read_alignment_entry(mvet_gguf_t *context,
                                                        mvet_gguf_kv_alignment_t *alignment,
                                                        mvet_gguf_kv_entry_t entry);

/* Enforces the required alignment tag. context is borrowed, non-NULL.
 * Halts for another valid GGUF tag. */
static mvet_istatus_t mvet_gguf_kv_check_alignment_tag(mvet_gguf_t *context,
                                                       mvet_gguf_kv_entry_t entry);

/* Parses one pending alignment scalar. Both pointers are borrowed, non-NULL.
 * Propagates cursor or budget status. */
static mvet_istatus_t mvet_gguf_kv_read_alignment_value(mvet_gguf_t *context,
                                                        mvet_gguf_kv_alignment_t *alignment);

/* Records the latest reserved-key scalar. alignment is borrowed, non-NULL.
 * No failure. */
static void mvet_gguf_kv_record_alignment_value(mvet_gguf_kv_alignment_t *alignment,
                                                size_t field_offset,
                                                uint32_t value);

/* Dispatches one ordinary outer value. context is borrowed, non-NULL.
 * Propagates value-parser status. */
static mvet_istatus_t
mvet_gguf_kv_read_value(mvet_gguf_t *context, uint32_t tag, size_t tag_offset);

/* Parses one bounded array. context is borrowed, non-NULL.
 * Propagates header, budget, or payload status. */
static mvet_istatus_t mvet_gguf_kv_read_array(mvet_gguf_t *context);

/* Parses one valid inner tag into array. Both pointers are borrowed,
 * non-NULL. Propagates cursor or tag-policy status. */
static mvet_istatus_t mvet_gguf_kv_read_array_tag(mvet_gguf_t *context,
                                                  mvet_gguf_kv_array_t *array);

/* Rejects an array-of-array shape. context is borrowed, non-NULL.
 * Halts for the forbidden tag. */
static mvet_istatus_t mvet_gguf_kv_check_nested_array(mvet_gguf_t *context,
                                                      mvet_gguf_kv_array_t array);

/* Enforces the inner-tag range. context is borrowed, non-NULL.
 * Halts for an unknown tag. */
static mvet_istatus_t mvet_gguf_kv_check_array_tag(mvet_gguf_t *context,
                                                   mvet_gguf_kv_array_t array);

/* Parses one capped array count into array. Both pointers are borrowed,
 * non-NULL. Propagates cursor or count-policy status. */
static mvet_istatus_t mvet_gguf_kv_read_array_count(mvet_gguf_t *context,
                                                    mvet_gguf_kv_array_t *array);

/* Enforces the array-count cap. context is borrowed, non-NULL.
 * Halts when count exceeds the cap. */
static mvet_istatus_t mvet_gguf_kv_check_array_count(mvet_gguf_t *context,
                                                     mvet_gguf_kv_array_t array);

/* Dispatches one bounded non-array payload. context is borrowed, non-NULL.
 * Propagates payload-parser status. */
static mvet_istatus_t
mvet_gguf_kv_read_payload(mvet_gguf_t *context, uint32_t tag, uint64_t count, size_t field_offset);

/* True for a scalar count or an array count within the configured cap. Pure. */
static bool mvet_gguf_kv_count_is_bounded(uint64_t count);

/* Skips one fixed-width payload. context is borrowed, non-NULL.
 * Propagates budget or cursor status. */
static mvet_istatus_t mvet_gguf_kv_skip_fixed(mvet_gguf_t *context,
                                              size_t field_offset,
                                              uint8_t element_bytes,
                                              uint64_t count);

/* Computes one fixed-width payload size into output_bytes. The output pointer
 * is borrowed, writable, non-NULL. Returns false on overflow. */
static bool
mvet_gguf_kv_get_payload_bytes(size_t *output_bytes, uint64_t count, uint8_t element_bytes);

/* Parses one bounded boolean payload. context is borrowed, non-NULL.
 * Propagates budget, cursor, or boolean-policy status. */
static mvet_istatus_t
mvet_gguf_kv_read_booleans(mvet_gguf_t *context, size_t field_offset, uint64_t count);

/* Enforces canonical boolean bytes. context is borrowed, non-NULL.
 * Halts at the first invalid byte. */
static mvet_istatus_t mvet_gguf_kv_check_booleans(mvet_gguf_t *context, mvet_span_t values);

/* Parses one bounded string sequence. context is borrowed, non-NULL.
 * Propagates string or budget status. */
static mvet_istatus_t mvet_gguf_kv_read_strings(mvet_gguf_t *context, uint64_t count);

/* Rejects duplicate key spans. context is borrowed, non-NULL.
 * Halts for the first sorted duplicate. */
static mvet_istatus_t mvet_gguf_kv_check_duplicates(mvet_gguf_t *context);

/* Reports a located duplicate. context is borrowed, non-NULL.
 * Always returns MVET_I_HALT. */
static mvet_istatus_t mvet_gguf_kv_reject_duplicate(mvet_gguf_t *context,
                                                    mvet_span_duplicate_t duplicate);

/* Validates pending alignment state. Both pointers are borrowed, non-NULL.
 * Propagates alignment-policy status. */
static mvet_istatus_t mvet_gguf_kv_apply_alignment(mvet_gguf_t *context,
                                                   const mvet_gguf_kv_alignment_t *alignment);

/* Enforces the alignment scalar policy. Both pointers are borrowed,
 * non-NULL. Halts for an invalid scalar. */
static mvet_istatus_t mvet_gguf_kv_check_alignment_value(mvet_gguf_t *context,
                                                         const mvet_gguf_kv_alignment_t *alignment);

/* Commits proven alignment state. Both pointers are borrowed, non-NULL.
 * No failure. */
static void mvet_gguf_kv_commit_alignment(mvet_gguf_t *context,
                                          const mvet_gguf_kv_alignment_t *alignment);

mvet_istatus_t mvet_gguf_kv_pass(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->kv_count <= MVET_MAX_KV_COUNT);

    mvet_gguf_kv_alignment_t alignment = {0};
    for (size_t entry_index = 0; entry_index < context->kv_count; entry_index++)
        MVET_TRY(mvet_gguf_kv_read_entry(context, &alignment, entry_index));
    MVET_TRY(mvet_gguf_kv_check_duplicates(context));
    return mvet_gguf_kv_apply_alignment(context, &alignment);
}

static mvet_istatus_t mvet_gguf_kv_read_entry(mvet_gguf_t *context,
                                              mvet_gguf_kv_alignment_t *alignment,
                                              size_t entry_index)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);
    MVET_ASSERT(entry_index < context->kv_count);

    mvet_gguf_kv_entry_t entry = {0};
    MVET_TRY(mvet_gguf_kv_read_key(context, &entry.key));
    mvet_gguf_kv_index_key(context, entry_index, entry.key);
    MVET_TRY(mvet_gguf_kv_read_tag(context, &entry));
    return mvet_gguf_kv_read_entry_value(context, alignment, entry);
}

static mvet_istatus_t mvet_gguf_kv_read_key(mvet_gguf_t *context, mvet_span_t *output_key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(output_key != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    size_t field_offset = cursor->offset;
    MVET_TRY(mvet_gguf_kv_read_string(context, output_key, MVET_GGUF_STRING_KEY));
    return mvet_gguf_kv_check_key(context, field_offset, *output_key);
}

static mvet_istatus_t mvet_gguf_kv_read_string(mvet_gguf_t *context,
                                               mvet_span_t *output_span,
                                               mvet_gguf_string_role_t role)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(output_span != NULL);
    MVET_ASSERT(role < MVET_GGUF_STRING_ROLE_COUNT);

    mvet_cursor_t *cursor = &context->cursor;
    mvet_gguf_string_header_t header = {0};
    MVET_TRY(mvet_gguf_string_read_header(cursor, &header, role));
    MVET_TRY(mvet_gguf_kv_charge_string(context, header));
    return mvet_gguf_string_read_body(cursor, output_span, header, role);
}

static mvet_istatus_t mvet_gguf_kv_charge_string(mvet_gguf_t *context,
                                                 mvet_gguf_string_header_t header)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(header.field_offset <= context->cursor.offset);

    uint64_t encoded_bytes = mvet_gguf_kv_get_string_bytes(header);
    return mvet_gguf_kv_charge_bytes(context, header.field_offset, encoded_bytes);
}

static uint64_t mvet_gguf_kv_get_string_bytes(mvet_gguf_string_header_t header)
{
    uint64_t encoded_bytes = 0;
    bool fits =
        mvet_checked_add_u64(&encoded_bytes, (uint64_t)header.length, MVET_GGUF_KV_LENGTH_BYTES);
    return fits ? encoded_bytes : UINT64_MAX;
}

static mvet_istatus_t
mvet_gguf_kv_charge_bytes(mvet_gguf_t *context, size_t field_offset, uint64_t byte_count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(field_offset <= context->cursor.length);

    mvet_gguf_kv_charge_t charge = {0};
    MVET_TRY(mvet_gguf_kv_check_charge(context, &charge, field_offset, byte_count));
    mvet_gguf_kv_commit_charge(context, charge);
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_kv_check_charge(mvet_gguf_t *context,
                                                mvet_gguf_kv_charge_t *output_charge,
                                                size_t field_offset,
                                                uint64_t byte_count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(output_charge != NULL);
    MVET_ASSERT(context->kv_encoded_bytes <= MVET_MAX_KV_TOTAL_BYTES);

    uint64_t projected_bytes = 0;
    bool fits = mvet_checked_add_u64(&projected_bytes, context->kv_encoded_bytes, byte_count);
    if (fits && projected_bytes <= MVET_MAX_KV_TOTAL_BYTES) {
        output_charge->total_bytes = projected_bytes;
        return MVET_I_OK;
    }

    uint64_t report_bytes = fits ? projected_bytes : UINT64_MAX;
    mvet_issue_t issue = mvet_issue_make(
        MVET_V_KV_TOTAL_BYTES_CAP, (uint64_t)field_offset, report_bytes, MVET_MAX_KV_TOTAL_BYTES);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static void mvet_gguf_kv_commit_charge(mvet_gguf_t *context, mvet_gguf_kv_charge_t charge)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(charge.total_bytes >= context->kv_encoded_bytes);
    MVET_ASSERT(charge.total_bytes <= MVET_MAX_KV_TOTAL_BYTES);

    context->kv_encoded_bytes = charge.total_bytes;
}

static mvet_istatus_t
mvet_gguf_kv_check_key(mvet_gguf_t *context, size_t field_offset, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(key.length <= MVET_MAX_KEY_BYTES);

    if (key.length != 0)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(MVET_V_KEY_EMPTY, (uint64_t)field_offset, 0, 0);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static void mvet_gguf_kv_index_key(mvet_gguf_t *context, size_t entry_index, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->key_spans != NULL);
    MVET_ASSERT(entry_index < context->kv_count);

    mvet_span_t *key_spans = context->key_spans;
    key_spans[entry_index] = key;
}

static mvet_istatus_t mvet_gguf_kv_read_tag(mvet_gguf_t *context, mvet_gguf_kv_entry_t *entry)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(entry != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    entry->tag_offset = cursor->offset;
    MVET_TRY(mvet_cursor_read_u32(cursor, &entry->tag));
    MVET_TRY(mvet_gguf_kv_check_tag(context, entry->tag_offset, entry->tag));
    return mvet_gguf_kv_charge_bytes(context, entry->tag_offset, MVET_GGUF_KV_TAG_BYTES);
}

static mvet_istatus_t
mvet_gguf_kv_check_tag(mvet_gguf_t *context, size_t field_offset, uint32_t tag)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(field_offset <= context->cursor.length);

    if (tag <= MVET_GGUF_TAG_MAX)
        return MVET_I_OK;

    mvet_issue_t issue =
        mvet_issue_make(MVET_V_KV_TYPE_RANGE, (uint64_t)field_offset, tag, MVET_GGUF_TAG_MAX);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static mvet_istatus_t mvet_gguf_kv_read_entry_value(mvet_gguf_t *context,
                                                    mvet_gguf_kv_alignment_t *alignment,
                                                    mvet_gguf_kv_entry_t entry)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);
    MVET_ASSERT(entry.tag <= MVET_GGUF_TAG_MAX);

    if (mvet_gguf_kv_is_alignment_key(context, entry.key))
        return mvet_gguf_kv_read_alignment_entry(context, alignment, entry);
    return mvet_gguf_kv_read_value(context, entry.tag, entry.tag_offset);
}

static bool mvet_gguf_kv_is_alignment_key(const mvet_gguf_t *context, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(key.length <= MVET_MAX_KEY_BYTES);

    const size_t key_length = sizeof(MVET_GGUF_KV_ALIGNMENT_KEY) - 1u;
    if (key.length != key_length)
        return false;

    const uint8_t *bytes = mvet_cursor_get_span_pointer(&context->cursor, key);
    for (size_t byte_index = 0; byte_index < key_length; byte_index++) {
        if (bytes[byte_index] != (uint8_t)MVET_GGUF_KV_ALIGNMENT_KEY[byte_index])
            return false;
    }
    return true;
}

static mvet_istatus_t mvet_gguf_kv_read_alignment_entry(mvet_gguf_t *context,
                                                        mvet_gguf_kv_alignment_t *alignment,
                                                        mvet_gguf_kv_entry_t entry)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);
    MVET_ASSERT(entry.tag <= MVET_GGUF_TAG_MAX);

    MVET_TRY(mvet_gguf_kv_check_alignment_tag(context, entry));
    return mvet_gguf_kv_read_alignment_value(context, alignment);
}

static mvet_istatus_t mvet_gguf_kv_check_alignment_tag(mvet_gguf_t *context,
                                                       mvet_gguf_kv_entry_t entry)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(entry.tag <= MVET_GGUF_TAG_MAX);

    if (entry.tag == MVET_GGUF_TAG_UINT32)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_ALIGN_TYPE, (uint64_t)entry.tag_offset, entry.tag, MVET_GGUF_TAG_UINT32);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static mvet_istatus_t mvet_gguf_kv_read_alignment_value(mvet_gguf_t *context,
                                                        mvet_gguf_kv_alignment_t *alignment)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    size_t field_offset = cursor->offset;
    MVET_TRY(mvet_gguf_kv_charge_bytes(context, field_offset, MVET_GGUF_KV_UINT32_BYTES));

    uint32_t value = 0;
    MVET_TRY(mvet_cursor_read_u32(cursor, &value));
    mvet_gguf_kv_record_alignment_value(alignment, field_offset, value);
    return MVET_I_OK;
}

static void mvet_gguf_kv_record_alignment_value(mvet_gguf_kv_alignment_t *alignment,
                                                size_t field_offset,
                                                uint32_t value)
{
    MVET_ASSERT(alignment != NULL);

    alignment->present = true;
    alignment->value_offset = field_offset;
    alignment->value = value;
}

static mvet_istatus_t mvet_gguf_kv_read_value(mvet_gguf_t *context, uint32_t tag, size_t tag_offset)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(tag <= MVET_GGUF_TAG_MAX);

    if (tag == MVET_GGUF_TAG_ARRAY)
        return mvet_gguf_kv_read_array(context);
    return mvet_gguf_kv_read_payload(context, tag, 1, tag_offset);
}

static mvet_istatus_t mvet_gguf_kv_read_array(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->cursor.offset <= context->cursor.length);

    mvet_gguf_kv_array_t array = {0};
    MVET_TRY(mvet_gguf_kv_read_array_tag(context, &array));
    MVET_TRY(mvet_gguf_kv_read_array_count(context, &array));
    MVET_TRY(mvet_gguf_kv_charge_bytes(context, array.tag_offset, MVET_GGUF_KV_ARRAY_HEADER_BYTES));
    return mvet_gguf_kv_read_payload(context, array.tag, array.count, array.count_offset);
}

static mvet_istatus_t mvet_gguf_kv_read_array_tag(mvet_gguf_t *context, mvet_gguf_kv_array_t *array)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(array != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    array->tag_offset = cursor->offset;
    MVET_TRY(mvet_cursor_read_u32(cursor, &array->tag));
    MVET_TRY(mvet_gguf_kv_check_nested_array(context, *array));
    return mvet_gguf_kv_check_array_tag(context, *array);
}

static mvet_istatus_t mvet_gguf_kv_check_nested_array(mvet_gguf_t *context,
                                                      mvet_gguf_kv_array_t array)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(array.tag_offset <= context->cursor.length);

    if (array.tag != MVET_GGUF_TAG_ARRAY)
        return MVET_I_OK;

    mvet_issue_t issue =
        mvet_issue_make(MVET_V_KV_ARRAY_NESTED, (uint64_t)array.tag_offset, array.tag, 0);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static mvet_istatus_t mvet_gguf_kv_check_array_tag(mvet_gguf_t *context, mvet_gguf_kv_array_t array)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(array.tag_offset <= context->cursor.length);

    if (array.tag <= MVET_GGUF_TAG_MAX)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_KV_ARRAY_TYPE_RANGE, (uint64_t)array.tag_offset, array.tag, MVET_GGUF_TAG_MAX);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static mvet_istatus_t mvet_gguf_kv_read_array_count(mvet_gguf_t *context,
                                                    mvet_gguf_kv_array_t *array)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(array != NULL);

    mvet_cursor_t *cursor = &context->cursor;
    array->count_offset = cursor->offset;
    MVET_TRY(mvet_cursor_read_u64(cursor, &array->count));
    return mvet_gguf_kv_check_array_count(context, *array);
}

static mvet_istatus_t mvet_gguf_kv_check_array_count(mvet_gguf_t *context,
                                                     mvet_gguf_kv_array_t array)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(array.count_offset <= context->cursor.length);

    if (array.count <= MVET_MAX_ARRAY_ELEMS)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_KV_ARRAY_ELEMS_CAP, (uint64_t)array.count_offset, array.count, MVET_MAX_ARRAY_ELEMS);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static mvet_istatus_t
mvet_gguf_kv_read_payload(mvet_gguf_t *context, uint32_t tag, uint64_t count, size_t field_offset)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(tag <= MVET_GGUF_TAG_MAX);
    MVET_ASSERT(tag != MVET_GGUF_TAG_ARRAY);

    if (!mvet_gguf_kv_count_is_bounded(count))
        return MVET_I_ERR_ARG;

    uint8_t element_bytes = mvet_gguf_kv_element_bytes[tag];
    mvet_istatus_t status = MVET_I_ERR_ARG;
    switch (tag) {
    case MVET_GGUF_TAG_BOOL:
        status = mvet_gguf_kv_read_booleans(context, field_offset, count);
        break;
    case MVET_GGUF_TAG_STRING:
        status = mvet_gguf_kv_read_strings(context, count);
        break;
    case MVET_GGUF_TAG_ARRAY:
        MVET_ASSERT(tag != MVET_GGUF_TAG_ARRAY);
        break;
    default:
        MVET_ASSERT(element_bytes != 0);
        status = mvet_gguf_kv_skip_fixed(context, field_offset, element_bytes, count);
        break;
    }
    return status;
}

static bool mvet_gguf_kv_count_is_bounded(uint64_t count)
{
    return count == 1 || count <= MVET_MAX_ARRAY_ELEMS;
}

static mvet_istatus_t mvet_gguf_kv_skip_fixed(mvet_gguf_t *context,
                                              size_t field_offset,
                                              uint8_t element_bytes,
                                              uint64_t count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(element_bytes != 0);
    MVET_ASSERT(mvet_gguf_kv_count_is_bounded(count));

    size_t byte_count = 0;
    bool fits = mvet_gguf_kv_get_payload_bytes(&byte_count, count, element_bytes);
    if (!fits)
        return MVET_I_ERR_ARG;

    MVET_TRY(mvet_gguf_kv_charge_bytes(context, field_offset, (uint64_t)byte_count));
    return mvet_cursor_skip(&context->cursor, byte_count);
}

static bool
mvet_gguf_kv_get_payload_bytes(size_t *output_bytes, uint64_t count, uint8_t element_bytes)
{
    MVET_ASSERT(output_bytes != NULL);
    MVET_ASSERT(element_bytes != 0);
    MVET_ASSERT(mvet_gguf_kv_count_is_bounded(count));

    uint64_t byte_count = 0;
    bool fits = mvet_checked_mul_u64(&byte_count, count, element_bytes);
    if (!fits)
        return false;
    return mvet_checked_u64_to_size(output_bytes, byte_count);
}

static mvet_istatus_t
mvet_gguf_kv_read_booleans(mvet_gguf_t *context, size_t field_offset, uint64_t count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(mvet_gguf_kv_count_is_bounded(count));

    size_t boolean_count = 0;
    bool fits = mvet_checked_u64_to_size(&boolean_count, count);
    if (!fits)
        return MVET_I_ERR_ARG;

    MVET_TRY(mvet_gguf_kv_charge_bytes(context, field_offset, count));
    mvet_span_t values = {0};
    MVET_TRY(mvet_cursor_take_span(&context->cursor, &values, boolean_count));
    return mvet_gguf_kv_check_booleans(context, values);
}

static mvet_istatus_t mvet_gguf_kv_check_booleans(mvet_gguf_t *context, mvet_span_t values)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(mvet_gguf_kv_count_is_bounded(values.length));

    const uint8_t *bytes = mvet_cursor_get_span_pointer(&context->cursor, values);
    for (size_t boolean_index = 0; boolean_index < values.length; boolean_index++) {
        if (bytes[boolean_index] <= 1u)
            continue;

        mvet_issue_t issue = mvet_issue_make(MVET_V_KV_BOOL_BYTE,
                                             (uint64_t)(values.offset + boolean_index),
                                             bytes[boolean_index],
                                             1);
        mvet_cursor_t *cursor = &context->cursor;
        return mvet_violation(cursor->report, issue);
    }
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_kv_read_strings(mvet_gguf_t *context, uint64_t count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(mvet_gguf_kv_count_is_bounded(count));

    size_t string_count = 0;
    bool fits = mvet_checked_u64_to_size(&string_count, count);
    if (!fits)
        return MVET_I_ERR_ARG;

    for (size_t string_index = 0; string_index < string_count; string_index++) {
        mvet_span_t value = {0};
        MVET_TRY(mvet_gguf_kv_read_string(context, &value, MVET_GGUF_STRING_VALUE));
    }
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_kv_check_duplicates(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->kv_count <= MVET_MAX_KV_COUNT);

    mvet_cursor_t *cursor = &context->cursor;
    mvet_span_t *key_spans = context->key_spans;
    mvet_span_sort(key_spans, context->kv_count, cursor->buffer);

    mvet_span_duplicate_t duplicate = {0};
    bool found = mvet_span_find_duplicate(&duplicate, key_spans, context->kv_count, cursor->buffer);
    if (!found)
        return MVET_I_OK;
    return mvet_gguf_kv_reject_duplicate(context, duplicate);
}

static mvet_istatus_t mvet_gguf_kv_reject_duplicate(mvet_gguf_t *context,
                                                    mvet_span_duplicate_t duplicate)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(duplicate.first_offset <= duplicate.second_offset);

    mvet_issue_t issue = mvet_issue_make(MVET_V_KEY_DUPLICATE,
                                         (uint64_t)duplicate.second_offset,
                                         (uint64_t)duplicate.first_offset,
                                         (uint64_t)duplicate.second_offset);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static mvet_istatus_t mvet_gguf_kv_apply_alignment(mvet_gguf_t *context,
                                                   const mvet_gguf_kv_alignment_t *alignment)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);

    if (!alignment->present)
        return MVET_I_OK;

    MVET_TRY(mvet_gguf_kv_check_alignment_value(context, alignment));
    mvet_gguf_kv_commit_alignment(context, alignment);
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_kv_check_alignment_value(mvet_gguf_t *context,
                                                         const mvet_gguf_kv_alignment_t *alignment)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);
    MVET_ASSERT(alignment->present);

    uint64_t value = alignment->value;
    bool is_power_of_two = value != 0 && (value & (value - 1u)) == 0;
    if (is_power_of_two && value <= MVET_MAX_ALIGNMENT)
        return MVET_I_OK;

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_ALIGN_VALUE, (uint64_t)alignment->value_offset, value, MVET_MAX_ALIGNMENT);
    mvet_cursor_t *cursor = &context->cursor;
    return mvet_violation(cursor->report, issue);
}

static void mvet_gguf_kv_commit_alignment(mvet_gguf_t *context,
                                          const mvet_gguf_kv_alignment_t *alignment)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(alignment != NULL);
    MVET_ASSERT(alignment->present);
    MVET_ASSERT(!context->alignment_present);

    context->alignment_present = true;
    context->alignment_value_offset = alignment->value_offset;
    context->alignment_value = alignment->value;
    context->alignment = alignment->value;
}
