/* gguf_string.c: owns role-governed GGUF string decoding.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


/* One string role's cap plus its rejection identities. */
typedef struct {
    uint64_t maximum_bytes;
    uint32_t length_violation;
    uint32_t utf8_violation;
} mvet_gguf_string_rule_t;

static const mvet_gguf_string_rule_t mvet_gguf_string_rules[MVET_GGUF_STRING_ROLE_COUNT] = {
    [MVET_GGUF_STRING_KEY] =
        {
            .maximum_bytes = MVET_MAX_KEY_BYTES,
            .length_violation = MVET_V_KEY_LEN_CAP,
            .utf8_violation = MVET_V_KEY_UTF8,
        },
    [MVET_GGUF_STRING_VALUE] =
        {
            .maximum_bytes = MVET_MAX_STRING_BYTES,
            .length_violation = MVET_V_STR_LEN_CAP,
            .utf8_violation = MVET_V_STR_UTF8,
        },
    [MVET_GGUF_STRING_NAME] =
        {
            .maximum_bytes = MVET_MAX_NAME_BYTES,
            .length_violation = MVET_V_NAME_LEN,
            .utf8_violation = MVET_V_NAME_UTF8,
        },
};

/* Returns the immutable rule for a valid role. */
static const mvet_gguf_string_rule_t *mvet_gguf_string_get_rule(mvet_gguf_string_role_t role);

/* Enforces a role's length cap on borrowed report storage. */
static mvet_istatus_t mvet_gguf_string_check_length(mvet_report_t *report,
                                                    const mvet_gguf_string_rule_t *rule,
                                                    size_t field_offset,
                                                    uint64_t declared_length);

/* Narrows one validated prefix into a non-NULL header output. */
static void mvet_gguf_string_set_header(mvet_gguf_string_header_t *output_header,
                                        size_t field_offset,
                                        uint64_t declared_length);

/* Enforces a role's UTF-8 rule on one bounds-checked span. */
static mvet_istatus_t
mvet_gguf_string_check_utf8(mvet_cursor_t *cursor, mvet_span_t span, mvet_gguf_string_role_t role);

mvet_istatus_t
mvet_gguf_string_read(mvet_cursor_t *cursor, mvet_span_t *output_span, mvet_gguf_string_role_t role)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(output_span != NULL);

    mvet_gguf_string_header_t header = {0};
    MVET_TRY(mvet_gguf_string_read_header(cursor, &header, role));
    return mvet_gguf_string_read_body(cursor, output_span, header, role);
}

mvet_istatus_t mvet_gguf_string_read_header(mvet_cursor_t *cursor,
                                            mvet_gguf_string_header_t *output_header,
                                            mvet_gguf_string_role_t role)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(output_header != NULL);
    MVET_ASSERT(role < MVET_GGUF_STRING_ROLE_COUNT);

    const mvet_gguf_string_rule_t *rule = mvet_gguf_string_get_rule(role);
    size_t field_offset = cursor->offset;
    uint64_t declared_length = 0;
    MVET_TRY(mvet_cursor_read_u64(cursor, &declared_length));
    MVET_TRY(mvet_gguf_string_check_length(cursor->report, rule, field_offset, declared_length));
    mvet_gguf_string_set_header(output_header, field_offset, declared_length);
    return MVET_I_OK;
}

mvet_istatus_t mvet_gguf_string_read_body(mvet_cursor_t *cursor,
                                          mvet_span_t *output_span,
                                          mvet_gguf_string_header_t header,
                                          mvet_gguf_string_role_t role)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(output_span != NULL);
    MVET_ASSERT(role < MVET_GGUF_STRING_ROLE_COUNT);

    mvet_span_t span = {0};
    MVET_TRY(mvet_cursor_take_span(cursor, &span, header.length));
    MVET_TRY(mvet_gguf_string_check_utf8(cursor, span, role));
    *output_span = span;
    return MVET_I_OK;
}

static const mvet_gguf_string_rule_t *mvet_gguf_string_get_rule(mvet_gguf_string_role_t role)
{
    MVET_ASSERT(role < MVET_GGUF_STRING_ROLE_COUNT);

    return &mvet_gguf_string_rules[role];
}

static mvet_istatus_t mvet_gguf_string_check_length(mvet_report_t *report,
                                                    const mvet_gguf_string_rule_t *rule,
                                                    size_t field_offset,
                                                    uint64_t declared_length)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(rule != NULL);

    if (declared_length <= rule->maximum_bytes)
        return MVET_I_OK;
    mvet_issue_t issue = mvet_issue_make(
        rule->length_violation, (uint64_t)field_offset, declared_length, rule->maximum_bytes);
    return mvet_violation(report, issue);
}

static void mvet_gguf_string_set_header(mvet_gguf_string_header_t *output_header,
                                        size_t field_offset,
                                        uint64_t declared_length)
{
    MVET_ASSERT(output_header != NULL);

    size_t length = 0;
    bool fits = mvet_checked_u64_to_size(&length, declared_length);
    MVET_ASSERT(fits);
    output_header->field_offset = field_offset;
    output_header->length = length;
}

static mvet_istatus_t
mvet_gguf_string_check_utf8(mvet_cursor_t *cursor, mvet_span_t span, mvet_gguf_string_role_t role)
{
    MVET_ASSERT(cursor != NULL);
    MVET_ASSERT(role < MVET_GGUF_STRING_ROLE_COUNT);

    uint64_t bad_index = 0;
    const uint8_t *bytes = mvet_cursor_get_span_pointer(cursor, span);
    if (mvet_utf8_is_valid(bytes, (uint64_t)span.length, &bad_index))
        return MVET_I_OK;

    const mvet_gguf_string_rule_t *rule = mvet_gguf_string_get_rule(role);
    mvet_issue_t issue =
        mvet_issue_make(rule->utf8_violation, (uint64_t)span.offset + bad_index, bad_index, 0);
    return mvet_violation(cursor->report, issue);
}
