/* Reads one tensor record into the dense-layout accumulator. */
static mvet_istatus_t mvet_gguf_tensor_read_record(mvet_gguf_t *context, size_t tensor_index);

/* Reads the bounded shape into a fresh tensor record. */
static mvet_istatus_t mvet_gguf_tensor_read_shape(mvet_gguf_t *context,
                                                  mvet_tensor_record_t *record);

/* Sole producer for a dimension count over MVET_MAX_DIMS. */
static mvet_istatus_t mvet_gguf_tensor_check_dims_cap(mvet_gguf_t *context,
                                                      const mvet_tensor_record_t *record);

/* Fills the whole shape with the implicit unit dimensions. Infallible. */
static void mvet_gguf_tensor_init_unit_shape(mvet_tensor_record_t *record);

/* Reads one explicit dimension into the element product. */
static mvet_istatus_t mvet_gguf_tensor_read_dimension(mvet_gguf_t *context,
                                                      mvet_tensor_record_t *record,
                                                      size_t dimension_index);

/* Sole producer for a zero or over-range dimension. */
static mvet_istatus_t mvet_gguf_tensor_check_dimension_range(mvet_gguf_t *context,
                                                             const mvet_tensor_record_t *record,
                                                             size_t dimension_index);

/* Folds one validated dimension into the element product. Sole producer
 * for element-count overflow. */
static mvet_istatus_t mvet_gguf_tensor_extend_element_count(mvet_gguf_t *context,
                                                            mvet_tensor_record_t *record,
                                                            size_t dimension_index);

/* Resolves the exact on-disk byte count from the just-read dtype. */
static mvet_istatus_t mvet_gguf_tensor_resolve_bytes(mvet_gguf_t *context,
                                                     mvet_tensor_record_t *record);

/* Reads the dtype. Violations: range, unsupported slot, block divisibility. */
static mvet_istatus_t mvet_gguf_tensor_read_dtype(mvet_gguf_t *context,
                                                  mvet_tensor_record_t *record);

/* Sole producer for a dtype slot past the table. */
static mvet_istatus_t mvet_gguf_tensor_check_dtype_range(mvet_gguf_t *context,
                                                         const mvet_tensor_record_t *record);

/* Sole producer for a removed or reserved dtype slot. */
static mvet_istatus_t mvet_gguf_tensor_check_dtype_supported(mvet_gguf_t *context,
                                                             const mvet_tensor_record_t *record,
                                                             mvet_gguf_dtype_t dtype);

/* Sole producer for a first dimension off the dtype block size. */
static mvet_istatus_t mvet_gguf_tensor_check_block_divisibility(mvet_gguf_t *context,
                                                                const mvet_tensor_record_t *record,
                                                                mvet_gguf_dtype_t dtype);

/* Computes exact tensor bytes from a validated shape and dtype. */
static mvet_istatus_t mvet_gguf_tensor_compute_bytes(mvet_gguf_t *context,
                                                     mvet_tensor_record_t *record,
                                                     mvet_gguf_dtype_t dtype);

/* Checks dense offset equality before extending the running total. */
static mvet_istatus_t mvet_gguf_tensor_account(mvet_gguf_t *context,
                                               const mvet_tensor_record_t *record);

/* Sole producer for a non-dense tensor data offset. */
static mvet_istatus_t mvet_gguf_tensor_check_offset_match(mvet_gguf_t *context,
                                                          const mvet_tensor_record_t *record);

/* Rounds a value up to the validated file alignment. Produces the
 * size-overflow violation when rounding wraps. */
static mvet_istatus_t mvet_gguf_tensor_align(mvet_gguf_t *context,
                                             uint64_t *aligned_value,
                                             uint64_t value,
                                             size_t field_offset);

/* Commits one padded tensor into the running dense total. */
static mvet_istatus_t mvet_gguf_tensor_extend_packed_bytes(mvet_gguf_t *context,
                                                           uint64_t padded_bytes,
                                                           size_t field_offset);

/* Sole producer for a failed tensor-size arithmetic operation. */
static mvet_istatus_t mvet_gguf_tensor_reject_size(mvet_gguf_t *context,
                                                   size_t field_offset,
                                                   uint64_t left,
                                                   uint64_t right);

/* Rejects a duplicate tensor name after deterministic sorting. */
static mvet_istatus_t mvet_gguf_tensor_check_duplicates(mvet_gguf_t *context);

/* Checks data-region extent against the whole input. */
static mvet_istatus_t mvet_gguf_tensor_check_layout(mvet_gguf_t *context);

/* Accepts the two legal endings of a file with no tensor data. */
static mvet_istatus_t
mvet_gguf_tensor_check_empty_end(mvet_gguf_t *context, uint64_t data_start, size_t metadata_offset);

/* Requires the file to end exactly at the padded data extent. Sole
 * producer for the data-extent violation. */
static mvet_istatus_t
mvet_gguf_tensor_check_data_end(mvet_gguf_t *context, uint64_t data_start, size_t metadata_offset);

/* Sole producer for bytes after the canonical file boundary. */
static mvet_istatus_t mvet_gguf_tensor_reject_trailing(mvet_gguf_t *context, uint64_t expected_end);

mvet_istatus_t mvet_gguf_tensor_pass(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->tensor_count <= MVET_MAX_TENSORS);

    for (size_t tensor_index = 0; tensor_index < context->tensor_count; tensor_index++)
        MVET_TRY(mvet_gguf_tensor_read_record(context, tensor_index));
    MVET_TRY(mvet_gguf_tensor_check_duplicates(context));
    return mvet_gguf_tensor_check_layout(context);
}

mvet_gguf_dtype_t mvet_gguf_get_dtype(uint32_t dtype)
{
    MVET_ASSERT(dtype < MVET_GGUF_DTYPE_COUNT);

    return mvet_gguf_dtype_table[dtype];
}

static mvet_istatus_t mvet_gguf_tensor_read_record(mvet_gguf_t *context, size_t tensor_index)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(tensor_index < context->tensor_count);

    mvet_tensor_record_t record = {0};
    MVET_TRY(mvet_gguf_string_read(&context->cursor, &record.name, MVET_GGUF_STRING_NAME));
    context->name_spans[tensor_index] = record.name;
    MVET_TRY(mvet_gguf_tensor_read_shape(context, &record));
    MVET_TRY(mvet_gguf_tensor_resolve_bytes(context, &record));

    record.data_offset_field = context->cursor.offset;
    MVET_TRY(mvet_cursor_read_u64(&context->cursor, &record.data_offset));
    return mvet_gguf_tensor_account(context, &record);
}

static mvet_istatus_t mvet_gguf_tensor_read_shape(mvet_gguf_t *context,
                                                  mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    record->dimension_count_offset = context->cursor.offset;
    MVET_TRY(mvet_cursor_read_u32(&context->cursor, &record->dimension_count));
    MVET_TRY(mvet_gguf_tensor_check_dims_cap(context, record));

    mvet_gguf_tensor_init_unit_shape(record);
    for (size_t dimension_index = 0; dimension_index < (size_t)record->dimension_count;
         dimension_index++)
        MVET_TRY(mvet_gguf_tensor_read_dimension(context, record, dimension_index));
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_check_dims_cap(mvet_gguf_t *context,
                                                      const mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    if (record->dimension_count <= MVET_MAX_DIMS)
        return MVET_I_OK;
    mvet_issue_t issue = mvet_issue_make(MVET_V_TENSOR_DIMS_CAP,
                                         (uint64_t)record->dimension_count_offset,
                                         record->dimension_count,
                                         MVET_MAX_DIMS);
    return mvet_violation(context->cursor.report, issue);
}

static void mvet_gguf_tensor_init_unit_shape(mvet_tensor_record_t *record)
{
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(record->dimension_count <= MVET_GGUF_DIMENSION_COUNT);

    record->element_count = 1;
    for (size_t dimension_index = 0; dimension_index < MVET_GGUF_DIMENSION_COUNT; dimension_index++)
        record->dimensions[dimension_index] = 1;
}

static mvet_istatus_t mvet_gguf_tensor_read_dimension(mvet_gguf_t *context,
                                                      mvet_tensor_record_t *record,
                                                      size_t dimension_index)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(dimension_index < MVET_GGUF_DIMENSION_COUNT);

    record->dimension_offsets[dimension_index] = context->cursor.offset;
    uint64_t dimension = 0;
    MVET_TRY(mvet_cursor_read_u64(&context->cursor, &dimension));
    record->dimensions[dimension_index] = dimension;
    MVET_TRY(mvet_gguf_tensor_check_dimension_range(context, record, dimension_index));
    return mvet_gguf_tensor_extend_element_count(context, record, dimension_index);
}

static mvet_istatus_t mvet_gguf_tensor_check_dimension_range(mvet_gguf_t *context,
                                                             const mvet_tensor_record_t *record,
                                                             size_t dimension_index)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(dimension_index < MVET_GGUF_DIMENSION_COUNT);

    uint64_t dimension = record->dimensions[dimension_index];
    if (dimension != 0 && dimension <= (uint64_t)INT64_MAX)
        return MVET_I_OK;
    mvet_issue_t issue = mvet_issue_make(MVET_V_TENSOR_NE_RANGE,
                                         (uint64_t)record->dimension_offsets[dimension_index],
                                         dimension,
                                         dimension_index);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t mvet_gguf_tensor_extend_element_count(mvet_gguf_t *context,
                                                            mvet_tensor_record_t *record,
                                                            size_t dimension_index)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(dimension_index < MVET_GGUF_DIMENSION_COUNT);
    MVET_ASSERT(record->dimensions[dimension_index] != 0);

    uint64_t dimension = record->dimensions[dimension_index];
    uint64_t largest_factor = ((uint64_t)INT64_MAX - 1u) / dimension;
    if (record->element_count > largest_factor) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_TENSOR_NE_OVERFLOW,
                                             (uint64_t)record->dimension_offsets[dimension_index],
                                             dimension,
                                             dimension_index);
        return mvet_violation(context->cursor.report, issue);
    }

    bool product_fits =
        mvet_checked_mul_u64(&record->element_count, record->element_count, dimension);
    MVET_ASSERT(product_fits);
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_resolve_bytes(mvet_gguf_t *context,
                                                     mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    MVET_TRY(mvet_gguf_tensor_read_dtype(context, record));
    mvet_gguf_dtype_t dtype = mvet_gguf_get_dtype(record->dtype);
    return mvet_gguf_tensor_compute_bytes(context, record, dtype);
}

static mvet_istatus_t mvet_gguf_tensor_read_dtype(mvet_gguf_t *context,
                                                  mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    record->dtype_offset = context->cursor.offset;
    MVET_TRY(mvet_cursor_read_u32(&context->cursor, &record->dtype));
    MVET_TRY(mvet_gguf_tensor_check_dtype_range(context, record));

    mvet_gguf_dtype_t dtype = mvet_gguf_get_dtype(record->dtype);
    MVET_TRY(mvet_gguf_tensor_check_dtype_supported(context, record, dtype));
    return mvet_gguf_tensor_check_block_divisibility(context, record, dtype);
}

static mvet_istatus_t mvet_gguf_tensor_check_dtype_range(mvet_gguf_t *context,
                                                         const mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    if (record->dtype < MVET_GGUF_DTYPE_COUNT)
        return MVET_I_OK;
    mvet_issue_t issue = mvet_issue_make(MVET_V_TENSOR_DTYPE_RANGE,
                                         (uint64_t)record->dtype_offset,
                                         record->dtype,
                                         MVET_GGUF_DTYPE_COUNT - 1u);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t mvet_gguf_tensor_check_dtype_supported(mvet_gguf_t *context,
                                                             const mvet_tensor_record_t *record,
                                                             mvet_gguf_dtype_t dtype)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    if (dtype.type_size != 0)
        return MVET_I_OK;
    mvet_issue_t issue = mvet_issue_make(
        MVET_V_TENSOR_DTYPE_UNSUPPORTED, (uint64_t)record->dtype_offset, record->dtype, 0);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t mvet_gguf_tensor_check_block_divisibility(mvet_gguf_t *context,
                                                                const mvet_tensor_record_t *record,
                                                                mvet_gguf_dtype_t dtype)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(dtype.block_size != 0);

    if (record->dimensions[0] % dtype.block_size == 0)
        return MVET_I_OK;
    size_t field_offset =
        record->dimension_count == 0 ? record->dtype_offset : record->dimension_offsets[0];
    mvet_issue_t issue = mvet_issue_make(MVET_V_TENSOR_BLOCK_DIVISIBILITY,
                                         (uint64_t)field_offset,
                                         record->dimensions[0],
                                         dtype.block_size);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t mvet_gguf_tensor_compute_bytes(mvet_gguf_t *context,
                                                     mvet_tensor_record_t *record,
                                                     mvet_gguf_dtype_t dtype)
{
    MVET_ASSERT(dtype.block_size != 0);
    MVET_ASSERT(record->element_count % dtype.block_size == 0);

    uint64_t block_count = record->element_count / dtype.block_size;
    bool byte_count_fits = mvet_checked_mul_u64(&record->byte_count, block_count, dtype.type_size);
    if (!byte_count_fits) {
        return mvet_gguf_tensor_reject_size(
            context, record->dtype_offset, block_count, dtype.type_size);
    }
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_account(mvet_gguf_t *context,
                                               const mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    MVET_TRY(mvet_gguf_tensor_check_offset_match(context, record));
    uint64_t padded = 0;
    MVET_TRY(mvet_gguf_tensor_align(context, &padded, record->byte_count, record->dtype_offset));
    return mvet_gguf_tensor_extend_packed_bytes(context, padded, record->data_offset_field);
}

static mvet_istatus_t mvet_gguf_tensor_check_offset_match(mvet_gguf_t *context,
                                                          const mvet_tensor_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);

    if (record->data_offset == context->packed_data_bytes)
        return MVET_I_OK;
    mvet_issue_t issue = mvet_issue_make(MVET_V_TENSOR_OFFSET_MISMATCH,
                                         (uint64_t)record->data_offset_field,
                                         record->data_offset,
                                         context->packed_data_bytes);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t mvet_gguf_tensor_align(mvet_gguf_t *context,
                                             uint64_t *aligned_value,
                                             uint64_t value,
                                             size_t field_offset)
{
    MVET_ASSERT(aligned_value != NULL);
    MVET_ASSERT(context->alignment != 0);
    MVET_ASSERT((context->alignment & (context->alignment - 1u)) == 0u);

    uint64_t remainder = value & (context->alignment - 1u);
    uint64_t padding = remainder == 0 ? 0 : context->alignment - remainder;
    bool alignment_fits = mvet_checked_add_u64(aligned_value, value, padding);
    if (!alignment_fits)
        return mvet_gguf_tensor_reject_size(context, field_offset, value, padding);
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_extend_packed_bytes(mvet_gguf_t *context,
                                                           uint64_t padded_bytes,
                                                           size_t field_offset)
{
    MVET_ASSERT(context != NULL);

    uint64_t total = 0;
    bool total_fits = mvet_checked_add_u64(&total, context->packed_data_bytes, padded_bytes);
    if (!total_fits) {
        return mvet_gguf_tensor_reject_size(
            context, field_offset, context->packed_data_bytes, padded_bytes);
    }
    MVET_ASSERT(total >= context->packed_data_bytes);
    context->packed_data_bytes = total;
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_reject_size(mvet_gguf_t *context,
                                                   size_t field_offset,
                                                   uint64_t left,
                                                   uint64_t right)
{
    mvet_issue_t issue =
        mvet_issue_make(MVET_V_TENSOR_SIZE_OVERFLOW, (uint64_t)field_offset, left, right);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t mvet_gguf_tensor_check_duplicates(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);

    mvet_span_sort(context->name_spans, context->tensor_count, context->cursor.buffer);

    mvet_span_duplicate_t duplicate = {0};
    if (mvet_span_find_duplicate(
            &duplicate, context->name_spans, context->tensor_count, context->cursor.buffer)) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_NAME_DUPLICATE,
                                             (uint64_t)duplicate.second_offset,
                                             (uint64_t)duplicate.first_offset,
                                             (uint64_t)duplicate.second_offset);
        return mvet_violation(context->cursor.report, issue);
    }
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_check_layout(mvet_gguf_t *context)
{
    MVET_ASSERT(context != NULL);

    size_t metadata_offset = context->cursor.offset;
    uint64_t data_start = 0;
    MVET_TRY(
        mvet_gguf_tensor_align(context, &data_start, (uint64_t)metadata_offset, metadata_offset));

    if (context->packed_data_bytes == 0)
        return mvet_gguf_tensor_check_empty_end(context, data_start, metadata_offset);
    return mvet_gguf_tensor_check_data_end(context, data_start, metadata_offset);
}

static mvet_istatus_t
mvet_gguf_tensor_check_empty_end(mvet_gguf_t *context, uint64_t data_start, size_t metadata_offset)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->packed_data_bytes == 0);

    bool ends_at_alignment = (uint64_t)context->cursor.length == data_start;
    bool ends_at_metadata = context->cursor.length == metadata_offset;
    if (ends_at_alignment || ends_at_metadata)
        return MVET_I_OK;
    return mvet_gguf_tensor_reject_trailing(context, data_start);
}

static mvet_istatus_t
mvet_gguf_tensor_check_data_end(mvet_gguf_t *context, uint64_t data_start, size_t metadata_offset)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->packed_data_bytes != 0);

    uint64_t data_end = 0;
    bool extent_fits = mvet_checked_add_u64(&data_end, data_start, context->packed_data_bytes);
    if (!extent_fits) {
        return mvet_gguf_tensor_reject_size(
            context, metadata_offset, data_start, context->packed_data_bytes);
    }
    uint64_t file_length = (uint64_t)context->cursor.length;
    if (data_end > file_length) {
        mvet_issue_t issue = mvet_issue_make(
            MVET_V_TENSOR_DATA_EXTENT, (uint64_t)metadata_offset, data_end, file_length);
        return mvet_violation(context->cursor.report, issue);
    }
    if (data_end < file_length)
        return mvet_gguf_tensor_reject_trailing(context, data_end);
    return MVET_I_OK;
}

static mvet_istatus_t mvet_gguf_tensor_reject_trailing(mvet_gguf_t *context, uint64_t expected_end)
{
    mvet_issue_t issue = mvet_issue_make(
        MVET_V_TRAILING_BYTES, expected_end, expected_end, (uint64_t)context->cursor.length);
    return mvet_violation(context->cursor.report, issue);
}
/* ---- src/report.c ---- */
/* report.c: owns every write to the verdict report: the fail-closed clear
 * and the single first-violation producer.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdint.h>


enum {
    MVET_REPORT_DETAIL_PRIMARY = 0,
    MVET_REPORT_DETAIL_SECONDARY = 1
};

mvet_issue_t mvet_issue_make(uint32_t code, uint64_t offset, uint64_t detail0, uint64_t detail1)
{
    mvet_issue_t issue = {
        .code = code,
        .offset = offset,
        .detail = {detail0, detail1},
    };
    return issue;
}

mvet_istatus_t mvet_violation(mvet_report_t *report, mvet_issue_t issue)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(issue.code != MVET_V_NONE);
    /* First-violation contract: nothing may have been recorded before. */
    MVET_ASSERT(report->violation == MVET_V_NONE);
    MVET_ASSERT(report->verdict == MVET_VERDICT_REJECT);

    report->violation = issue.code;
    report->offset = issue.offset;
    report->detail[MVET_REPORT_DETAIL_PRIMARY] = issue.detail[MVET_REPORT_DETAIL_PRIMARY];
    report->detail[MVET_REPORT_DETAIL_SECONDARY] = issue.detail[MVET_REPORT_DETAIL_SECONDARY];
    return MVET_I_HALT;
}

void mvet_report_clear(mvet_report_t *report)
{
    MVET_ASSERT(report != NULL);

    report->verdict = MVET_VERDICT_REJECT;
    report->violation = MVET_V_NONE;
    report->offset = 0;
    report->detail[MVET_REPORT_DETAIL_PRIMARY] = 0;
    report->detail[MVET_REPORT_DETAIL_SECONDARY] = 0;
}
/* ---- src/span.c ---- */
/* span.c: owns deterministic ordering and duplicate detection for spans.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


enum {
    MVET_SPAN_HEAP_ARITY = 2
};

typedef enum {
    MVET_SPAN_ORDER_BEFORE = -1,
    MVET_SPAN_ORDER_EQUAL = 0,
    MVET_SPAN_ORDER_AFTER = 1
} mvet_span_order_t;

/* Compares two ranges lexicographically. Pure. */
static mvet_span_order_t
mvet_span_compare(mvet_span_t left, mvet_span_t right, const uint8_t *buffer);

/* Exchanges two span values. */
static void mvet_span_swap(mvet_span_t *left, mvet_span_t *right);

/* Restores the max-heap below root in a bounded span prefix. */
static void
mvet_span_sift_down(mvet_span_t *spans, size_t count, size_t root, const uint8_t *buffer);

void mvet_span_sort(mvet_span_t *spans, size_t count, const uint8_t *buffer)
{
    MVET_ASSERT(spans != NULL || count == 0);
    MVET_ASSERT(buffer != NULL || count == 0);

    if (count < MVET_SPAN_HEAP_ARITY)
        return;
    for (size_t start = count / MVET_SPAN_HEAP_ARITY; start > 0; start--)
        mvet_span_sift_down(spans, count, start - 1u, buffer);
    for (size_t end = count - 1u; end > 0; end--) {
        mvet_span_swap(&spans[0], &spans[end]);
        mvet_span_sift_down(spans, end, 0, buffer);
    }
}

bool mvet_span_find_duplicate(mvet_span_duplicate_t *result,
                              const mvet_span_t *spans,
                              size_t count,
                              const uint8_t *buffer)
{
    MVET_ASSERT(result != NULL);
    MVET_ASSERT(spans != NULL || count == 0);
    MVET_ASSERT(buffer != NULL || count == 0);

    for (size_t span_index = 0; span_index + 1u < count; span_index++) {
        mvet_span_t left = spans[span_index];
        mvet_span_t right = spans[span_index + 1u];
        if (mvet_span_compare(left, right, buffer) != MVET_SPAN_ORDER_EQUAL)
            continue;
        result->first_offset = left.offset < right.offset ? left.offset : right.offset;
        result->second_offset = left.offset < right.offset ? right.offset : left.offset;
        return true;
    }
    return false;
}

static mvet_span_order_t
mvet_span_compare(mvet_span_t left, mvet_span_t right, const uint8_t *buffer)
{
    size_t common_length = left.length < right.length ? left.length : right.length;
    MVET_ASSERT(buffer != NULL || common_length == 0);

    /* Sorting is the only superlinear term in the library; charging
     * every compared byte is what makes that term measurable. */
    MVET_WORK_ADD(common_length + 1u);

    for (size_t byte_index = 0; byte_index < common_length; byte_index++) {
        uint8_t left_byte = buffer[left.offset + byte_index];
        uint8_t right_byte = buffer[right.offset + byte_index];
        if (left_byte != right_byte) {
            return left_byte < right_byte ? MVET_SPAN_ORDER_BEFORE : MVET_SPAN_ORDER_AFTER;
        }
    }
    if (left.length == right.length)
        return MVET_SPAN_ORDER_EQUAL;
    return left.length < right.length ? MVET_SPAN_ORDER_BEFORE : MVET_SPAN_ORDER_AFTER;
}

static void mvet_span_swap(mvet_span_t *left, mvet_span_t *right)
{
    MVET_ASSERT(left != NULL);
    MVET_ASSERT(right != NULL);

    mvet_span_t held = *left;
    *left = *right;
    *right = held;
}

static void
mvet_span_sift_down(mvet_span_t *spans, size_t count, size_t root, const uint8_t *buffer)
{
    MVET_ASSERT(spans != NULL);
    MVET_ASSERT(root < count);

    while (root < count / MVET_SPAN_HEAP_ARITY) {
        size_t child = root * MVET_SPAN_HEAP_ARITY + 1u;
        if (child + 1u < count &&
            mvet_span_compare(spans[child], spans[child + 1u], buffer) == MVET_SPAN_ORDER_BEFORE) {
            child++;
        }
        if (mvet_span_compare(spans[root], spans[child], buffer) != MVET_SPAN_ORDER_BEFORE) {
            return;
        }
        mvet_span_swap(&spans[root], &spans[child]);
        root = child;
    }
}
/* ---- src/st.c ---- */
/* st.c: public entry point for safetensors verification; owns argument
 * validation, pass sequencing, and the mapping from internal pass
 * status to API status.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stddef.h>
#include <stdint.h>


/* One validated whole-buffer input view. */
typedef struct {
    const uint8_t *buffer;
    size_t length;
} mvet_st_input_t;

/* Rejects a NULL report. report is caller-owned; NULL is accepted for validation.
 * Fails with MVET_ERR_ARG. */
static mvet_status_t mvet_st_validate_report(const mvet_report_t *report);

/* Validates the public arena/input contract. arena is borrowed; NULL is accepted for
 * validation. buffer is borrowed; NULL requires zero length. Fails with MVET_ERR_ARG. */
static mvet_status_t
mvet_st_validate_input(const mvet_arena_t *arena, const void *buffer, size_t length);

/* Resets the arena high-water mark. arena is non-NULL caller-owned storage. Infallible. */
static void mvet_st_reset_arena(mvet_arena_t *arena);

/* Returns a validated byte view. buffer is borrowed; NULL is permitted only at zero length.
 * Infallible. */
static mvet_st_input_t mvet_st_make_input(const void *buffer, size_t length);

/* Runs the three validation passes in file order. report is non-NULL caller-owned state.
 * arena is non-NULL caller-owned state. input borrows the whole buffer. */
static mvet_istatus_t
mvet_st_run_passes(mvet_report_t *report, mvet_arena_t *arena, mvet_st_input_t input);

/* Returns a fresh pass context. arena is non-NULL borrowed state. Infallible. */
static mvet_st_t mvet_st_make_context(mvet_arena_t *arena);

/* Completes the public result for status. report is non-NULL caller-owned state. Infallible. */
static mvet_status_t mvet_st_map_status(mvet_report_t *report, mvet_istatus_t status);

/* Marks a fail-closed report as structurally accepted. report is non-NULL caller-owned state.
 * Infallible. This is the only safetensors writer of MVET_VERDICT_ACCEPT. */
static void mvet_st_accept_report(mvet_report_t *report);

/* Returns the public API error for an internal API failure. Pure. */
static mvet_status_t mvet_st_map_error(mvet_istatus_t status);

mvet_status_t
mvet_st_verify(mvet_report_t *report, mvet_arena_t *arena, const void *buffer, size_t length)
{
    mvet_status_t public_status = mvet_st_validate_report(report);
    if (public_status != MVET_OK)
        return public_status;

    mvet_report_clear(report);
    public_status = mvet_st_validate_input(arena, buffer, length);
    if (public_status != MVET_OK)
        return public_status;

    mvet_st_reset_arena(arena);
    mvet_st_input_t input = mvet_st_make_input(buffer, length);

    mvet_istatus_t status = mvet_st_run_passes(report, arena, input);
    return mvet_st_map_status(report, status);
}

static mvet_status_t mvet_st_validate_report(const mvet_report_t *report)
{
    if (report == NULL)
        return MVET_ERR_ARG;
    return MVET_OK;
}

static mvet_status_t
mvet_st_validate_input(const mvet_arena_t *arena, const void *buffer, size_t length)
{
    if (arena == NULL)
        return MVET_ERR_ARG;
    if (buffer == NULL && length != 0)
        return MVET_ERR_ARG;
    if (arena->base == NULL && arena->capacity != 0)
        return MVET_ERR_ARG;
    return MVET_OK;
}

static void mvet_st_reset_arena(mvet_arena_t *arena)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(arena->base != NULL || arena->capacity == 0);

    arena->used = 0;
    MVET_ASSERT(arena->used <= arena->capacity);
}

static mvet_st_input_t mvet_st_make_input(const void *buffer, size_t length)
{
    MVET_ASSERT(buffer != NULL || length == 0);

    return (mvet_st_input_t){
        .buffer = (const uint8_t *)buffer,
        .length = length,
    };
}

static mvet_istatus_t
mvet_st_run_passes(mvet_report_t *report, mvet_arena_t *arena, mvet_st_input_t input)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(arena != NULL);

    mvet_st_t context = mvet_st_make_context(arena);
    mvet_cursor_t *cursor = &context.cursor;
    mvet_cursor_bind(cursor, report, input.buffer, input.length);

    mvet_istatus_t status = mvet_st_frame_pass(&context);
    if (status != MVET_I_OK)
        return status;

    status = mvet_st_header_pass(&context);
    if (status != MVET_I_OK)
        return status;
    return mvet_st_layout_pass(&context);
}

static mvet_st_t mvet_st_make_context(mvet_arena_t *arena)
{
    MVET_ASSERT(arena != NULL);
    MVET_ASSERT(arena->used == 0);

    mvet_st_t context = {
        .arena = arena,
    };
    MVET_ASSERT(context.arena == arena);
    MVET_ASSERT(context.tensor_count == 0);
    return context;
}

static mvet_status_t mvet_st_map_status(mvet_report_t *report, mvet_istatus_t status)
{
    MVET_ASSERT(report != NULL);

    if (status == MVET_I_OK) {
        mvet_st_accept_report(report);
        return MVET_OK;
    }
    if (status == MVET_I_HALT)
        return MVET_OK; /* report already carries the violation */

    mvet_report_clear(report);
    return mvet_st_map_error(status);
}

static void mvet_st_accept_report(mvet_report_t *report)
{
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(report->verdict == MVET_VERDICT_REJECT);
    MVET_ASSERT(report->violation == MVET_V_NONE);

    report->verdict = MVET_VERDICT_ACCEPT;
    MVET_ASSERT(report->verdict == MVET_VERDICT_ACCEPT);
}

static mvet_status_t mvet_st_map_error(mvet_istatus_t status)
{
    MVET_ASSERT(status != MVET_I_OK);
    MVET_ASSERT(status != MVET_I_HALT);

    if (status == MVET_I_ERR_ARENA)
        return MVET_ERR_ARENA;
    return MVET_ERR_ARG;
}
/* ---- src/st_header.c ---- */
/* st_header.c: owns the safetensors frame, the header JSON walk, and
 * duplicate-key detection over both key namespaces.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


#define MVET_ST_METADATA_KEY "__metadata__"

enum {
    MVET_ST_METADATA_KEY_BYTES = 12
};

/* Loop limits sit one past what the caps admit: the tensor cap and the
 * single-metadata rule bound root entries by MVET_MAX_ST_TENSORS + 1,
 * and the metadata cap bounds metadata entries. size_t expressions, not
 * enum constants, so cap overrides past INT_MAX stay well-defined. */
#define MVET_ST_ROOT_ENTRY_LIMIT ((size_t)MVET_MAX_ST_TENSORS + 2u)
#define MVET_ST_METADATA_ENTRY_LIMIT ((size_t)MVET_MAX_ST_METADATA_ENTRIES + 1u)

/* Sole producer for a header length past the cap. */
static mvet_istatus_t mvet_st_reject_header_cap(mvet_st_t *context, uint64_t declared);

/* Sizes and carves the three work arrays from the header length.
 * Fails with MVET_I_ERR_ARENA when a carve cannot fit. */
static mvet_istatus_t mvet_st_carve_work_arrays(mvet_st_t *context, size_t header_length);

/* Carves one work array. count then element_bytes follow the output.
 * Fails with MVET_I_ERR_ARENA when the carve cannot fit. */
static mvet_istatus_t
mvet_st_carve_array(mvet_st_t *context, void **array, size_t count, size_t element_bytes);

/* Smaller of the cap and the entry bound the header length admits. Pure. */
static size_t mvet_st_carve_bound(size_t header_length, size_t divisor, size_t cap);

/* Walks the root object's entries and dispatches each one. */
static mvet_istatus_t mvet_st_walk_root(mvet_st_t *context, mvet_st_json_t *json);

/* Handles one root entry from its key through the separator. */
static mvet_istatus_t
mvet_st_walk_root_entry(mvet_st_t *context, mvet_st_json_t *json, bool *closed);

/* Handles one root entry after its key. */
static mvet_istatus_t mvet_st_root_entry(mvet_st_t *context, mvet_st_json_t *json, mvet_span_t key);

/* Records one root key span. Infallible; the carve bound admits it. */
static void mvet_st_record_root_key(mvet_st_t *context, mvet_span_t key);

/* Enforces the single-__metadata__ rule, then walks the map. */
static mvet_istatus_t
mvet_st_enter_metadata(mvet_st_t *context, mvet_st_json_t *json, mvet_span_t key);

/* Walks the __metadata__ string map. */
static mvet_istatus_t mvet_st_walk_metadata(mvet_st_t *context, mvet_st_json_t *json);

/* Handles one metadata entry from its key through the separator. */
static mvet_istatus_t
mvet_st_walk_metadata_entry(mvet_st_t *context, mvet_st_json_t *json, bool *closed);

/* Handles one metadata entry after its key. */
static mvet_istatus_t
mvet_st_metadata_entry(mvet_st_t *context, mvet_st_json_t *json, mvet_span_t key);

/* Rejects byte-identical keys within one namespace via the sorted span
 * index. spans are mutated (sorted) in place. */
static mvet_istatus_t
mvet_st_check_duplicates(mvet_st_t *context, mvet_span_t *spans, size_t count);

/* Sole producer for byte-identical keys within one namespace. */
static mvet_istatus_t
mvet_st_reject_duplicate(mvet_st_t *context, size_t first_offset, size_t second_offset);

mvet_istatus_t mvet_st_frame_pass(mvet_st_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->cursor.offset == 0);

    uint64_t declared = 0;
    MVET_TRY(mvet_cursor_read_u64(&context->cursor, &declared));
    if (declared > (uint64_t)MVET_MAX_ST_HEADER_BYTES)
        return mvet_st_reject_header_cap(context, declared);

    /* The cap fits size_t (static assert), so the narrow cannot fail. */
    size_t header_length = 0;
    bool narrowed = mvet_checked_u64_to_size(&header_length, declared);
    MVET_ASSERT(narrowed);
    MVET_TRY(mvet_cursor_take_span(&context->cursor, &context->header, header_length));
    context->data_region_bytes = (uint64_t)(context->cursor.length - context->cursor.offset);
    return mvet_st_carve_work_arrays(context, header_length);
}

static mvet_istatus_t mvet_st_carve_work_arrays(mvet_st_t *context, size_t header_length)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->root_key_spans == NULL);

    context->root_key_bound = mvet_st_carve_bound(
        header_length, MVET_ST_MIN_ROOT_ENTRY_BYTES, (size_t)MVET_MAX_ST_TENSORS + 1u);
    context->metadata_key_bound = mvet_st_carve_bound(
        header_length, MVET_ST_MIN_METADATA_ENTRY_BYTES, (size_t)MVET_MAX_ST_METADATA_ENTRIES);
    context->extent_bound = mvet_st_carve_bound(
        header_length, MVET_ST_MIN_TENSOR_ENTRY_BYTES, (size_t)MVET_MAX_ST_TENSORS);

    MVET_TRY(mvet_st_carve_array(
        context, (void **)&context->root_key_spans, context->root_key_bound, sizeof(mvet_span_t)));
    MVET_TRY(mvet_st_carve_array(context,
                                 (void **)&context->metadata_key_spans,
                                 context->metadata_key_bound,
                                 sizeof(mvet_span_t)));
    return mvet_st_carve_array(
        context, (void **)&context->extents, context->extent_bound, sizeof(mvet_st_extent_t));
}

mvet_istatus_t mvet_st_header_pass(mvet_st_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->root_key_spans != NULL);

    mvet_st_json_t json = {0};
    mvet_st_json_bind(&json, context->cursor.report, context->cursor.buffer, context->header);

    MVET_TRY(mvet_st_walk_root(context, &json));
    mvet_st_json_skip_ws(&json);
    if (!mvet_st_json_at_end(&json))
        return mvet_st_json_reject_here(&json);

    MVET_TRY(mvet_st_check_duplicates(context, context->root_key_spans, context->root_key_count));
    return mvet_st_check_duplicates(
        context, context->metadata_key_spans, context->metadata_key_count);
}

static mvet_istatus_t mvet_st_reject_header_cap(mvet_st_t *context, uint64_t declared)
{
    MVET_ASSERT(context != NULL);

    mvet_issue_t issue =
        mvet_issue_make(MVET_V_ST_HEADER_LEN_CAP, 0, declared, MVET_MAX_ST_HEADER_BYTES);
    return mvet_violation(context->cursor.report, issue);
}

static mvet_istatus_t
mvet_st_carve_array(mvet_st_t *context, void **array, size_t count, size_t element_bytes)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(array != NULL);
    MVET_ASSERT(element_bytes != 0);

    uint64_t wide_bytes = 0;
    bool product_fits = mvet_checked_mul_u64(&wide_bytes, (uint64_t)count, (uint64_t)element_bytes);
    if (!product_fits)
        return MVET_I_ERR_ARENA;
    size_t allocation_bytes = 0;
    if (!mvet_checked_u64_to_size(&allocation_bytes, wide_bytes))
        return MVET_I_ERR_ARENA;
    return mvet_arena_allocate(context->arena, array, allocation_bytes);
}

static size_t mvet_st_carve_bound(size_t header_length, size_t divisor, size_t cap)
{
    MVET_ASSERT(divisor != 0);

    size_t admitted = header_length / divisor + 1u;
    return admitted < cap ? admitted : cap;
}

static mvet_istatus_t mvet_st_walk_root(mvet_st_t *context, mvet_st_json_t *json)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);

    mvet_st_json_skip_ws(json);
    bool empty = false;
    MVET_TRY(mvet_st_json_open_sequence(json, '{', '}', &empty));
    if (empty)
        return MVET_I_OK;

    for (size_t entry = 0; entry < MVET_ST_ROOT_ENTRY_LIMIT; entry++) {
        bool closed = false;
        MVET_TRY(mvet_st_walk_root_entry(context, json, &closed));
        if (closed)
            return MVET_I_OK;
    }
    /* Unreachable: the caps bound entries below the loop limit. Fail
     * closed rather than assert against a hostile input. */
    return mvet_st_json_reject_here(json);
}

static mvet_istatus_t
mvet_st_walk_root_entry(mvet_st_t *context, mvet_st_json_t *json, bool *closed)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(closed != NULL);

    mvet_span_t key = {0};
    MVET_TRY(mvet_st_json_read_key(json, &key));
    mvet_st_json_skip_ws(json);
    MVET_TRY(mvet_st_json_expect(json, ':'));
    mvet_st_json_skip_ws(json);
    MVET_TRY(mvet_st_root_entry(context, json, key));
    return mvet_st_json_continue_sequence(json, '}', closed);
}

static mvet_istatus_t mvet_st_root_entry(mvet_st_t *context, mvet_st_json_t *json, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);

    mvet_st_record_root_key(context, key);
    bool is_metadata =
        mvet_st_json_span_is(json, key, MVET_ST_METADATA_KEY, MVET_ST_METADATA_KEY_BYTES);
    if (is_metadata)
        return mvet_st_enter_metadata(context, json, key);
    return mvet_st_tensor_entry(context, json);
}

static void mvet_st_record_root_key(mvet_st_t *context, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    /* Every root entry spends at least MVET_ST_MIN_ROOT_ENTRY_BYTES
     * header bytes, so the carve bound strictly exceeds the count. */
    MVET_ASSERT(context->root_key_count < context->root_key_bound);

    context->root_key_spans[context->root_key_count] = key;
    context->root_key_count++;
}

static mvet_istatus_t
mvet_st_enter_metadata(mvet_st_t *context, mvet_st_json_t *json, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);

    if (context->metadata_seen)
        return mvet_st_reject_duplicate(context, context->metadata_key_offset, key.offset);
    context->metadata_seen = true;
    context->metadata_key_offset = key.offset;
    return mvet_st_walk_metadata(context, json);
}

static mvet_istatus_t mvet_st_walk_metadata(mvet_st_t *context, mvet_st_json_t *json)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);

    bool empty = false;
    MVET_TRY(mvet_st_json_open_sequence(json, '{', '}', &empty));
    if (empty)
        return MVET_I_OK;

    for (size_t entry = 0; entry < MVET_ST_METADATA_ENTRY_LIMIT; entry++) {
        bool closed = false;
        MVET_TRY(mvet_st_walk_metadata_entry(context, json, &closed));
        if (closed)
            return MVET_I_OK;
    }
    /* Unreachable: the metadata cap fires before the loop limit. */
    return mvet_st_json_reject_here(json);
}

static mvet_istatus_t
mvet_st_walk_metadata_entry(mvet_st_t *context, mvet_st_json_t *json, bool *closed)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(closed != NULL);

    mvet_span_t key = {0};
    MVET_TRY(mvet_st_json_read_key(json, &key));
    MVET_TRY(mvet_st_metadata_entry(context, json, key));
    return mvet_st_json_continue_sequence(json, '}', closed);
}

static mvet_istatus_t
mvet_st_metadata_entry(mvet_st_t *context, mvet_st_json_t *json, mvet_span_t key)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);

    if (context->metadata_key_count >= (size_t)MVET_MAX_ST_METADATA_ENTRIES) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_METADATA_COUNT_CAP,
                                             (uint64_t)key.offset,
                                             (uint64_t)context->metadata_key_count + 1u,
                                             MVET_MAX_ST_METADATA_ENTRIES);
        return mvet_violation(context->cursor.report, issue);
    }
    /* Every metadata entry spends at least MVET_ST_MIN_METADATA_ENTRY_BYTES
     * header bytes, so the carve bound strictly exceeds the count. */
    MVET_ASSERT(context->metadata_key_count < context->metadata_key_bound);
    context->metadata_key_spans[context->metadata_key_count] = key;
    context->metadata_key_count++;

    mvet_st_json_skip_ws(json);
    MVET_TRY(mvet_st_json_expect(json, ':'));
    mvet_st_json_skip_ws(json);
    mvet_span_t value = {0};
    return mvet_st_json_read_string(json, &value);
}

static mvet_istatus_t mvet_st_check_duplicates(mvet_st_t *context, mvet_span_t *spans, size_t count)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(spans != NULL || count == 0);

    mvet_span_sort(spans, count, context->cursor.buffer);
    mvet_span_duplicate_t duplicate = {0};
    if (mvet_span_find_duplicate(&duplicate, spans, count, context->cursor.buffer)) {
        return mvet_st_reject_duplicate(context, duplicate.first_offset, duplicate.second_offset);
    }
    return MVET_I_OK;
}

static mvet_istatus_t
mvet_st_reject_duplicate(mvet_st_t *context, size_t first_offset, size_t second_offset)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(first_offset < second_offset);

    mvet_issue_t issue = mvet_issue_make(MVET_V_ST_KEY_DUPLICATE,
                                         (uint64_t)second_offset,
                                         (uint64_t)first_offset,
                                         (uint64_t)second_offset);
    return mvet_violation(context->cursor.report, issue);
}
/* ---- src/st_json.c ---- */
/* st_json.c: owns the lexical layer of the safetensors header JSON:
 * whitespace, punctuation, strings under the escape policy, and strict
 * unsigned integers. All six lexical violation codes are produced here.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


enum {
    MVET_ST_JSON_CONTROL_LIMIT = 0x20, /* unescaped bytes below are illegal */
    MVET_ST_JSON_HEX_DIGITS = 4,
    MVET_ST_JSON_HEX_BASE = 16,
    MVET_ST_JSON_DECIMAL_BASE = 10,
    MVET_ST_JSON_SURROGATE_HIGH_FIRST = 0xd800,
    MVET_ST_JSON_SURROGATE_HIGH_LAST = 0xdbff,
    MVET_ST_JSON_SURROGATE_LOW_FIRST = 0xdc00,
    MVET_ST_JSON_SURROGATE_LOW_LAST = 0xdfff
};

/* True for the canonical JSON whitespace set. Pure. */
static bool mvet_st_json_is_ws(uint8_t byte);

/* Scans one string token from its opening quote. span receives the raw
 * content range; escapes are validated or rejected per allow_escapes. */
static mvet_istatus_t
mvet_st_json_scan_string(mvet_st_json_t *json, mvet_span_t *span, bool allow_escapes);

/* Consumes one string-content byte: escapes dispatch per the caller's
 * policy and unescaped control bytes reject. */
static mvet_istatus_t mvet_st_json_scan_content_byte(mvet_st_json_t *json, bool allow_escapes);

/* Handles one backslash under the caller's escape policy. json sits on
 * the backslash. Sole producer for a key escape (policy). */
static mvet_istatus_t mvet_st_json_scan_escape(mvet_st_json_t *json, bool allow_escapes);

/* Validates one escape sequence past its backslash. */
static mvet_istatus_t mvet_st_json_check_escape(mvet_st_json_t *json, size_t backslash_index);

/* True for the single-byte JSON escape designators. Pure. */
static bool mvet_st_json_is_simple_escape(uint8_t designator);

/* Validates one \u escape, including a required surrogate pair. */
static mvet_istatus_t mvet_st_json_check_unicode_escape(mvet_st_json_t *json,
                                                        size_t backslash_index);

/* Reads four hex digits into value. False when a digit is missing;
 * consumption stops at the offending byte then. */
static bool mvet_st_json_read_hex4(mvet_st_json_t *json, uint32_t *value);

/* Writes one hex digit's value. False for a non-hex byte. Pure. */
static bool mvet_st_json_hex_value(uint8_t byte, uint32_t *value);

/* Sole producer for an invalid or unpaired escape sequence. */
static mvet_istatus_t mvet_st_json_reject_escape(const mvet_st_json_t *json,
                                                 size_t backslash_index);

/* Strict UTF-8 over the span's raw bytes. Sole producer for a
 * malformed string byte. */
static mvet_istatus_t mvet_st_json_check_utf8(const mvet_st_json_t *json, mvet_span_t span);

/* True for an ASCII decimal digit. Pure. */
static bool mvet_st_json_is_digit(uint8_t byte);

/* True for a byte that would continue a number as a float. Pure. */
static bool mvet_st_json_is_number_tail(uint8_t byte);

/* Accumulates a nonzero decimal digit run with checked arithmetic. */
static mvet_istatus_t
mvet_st_json_read_digits(mvet_st_json_t *json, uint64_t *accumulated, size_t number_index);

/* Sole producer for a malformed or over-wide number. */
static mvet_istatus_t mvet_st_json_reject_number(const mvet_st_json_t *json, size_t number_index);

void mvet_st_json_bind(mvet_st_json_t *json,
                       mvet_report_t *report,
                       const uint8_t *buffer,
                       mvet_span_t header)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(report != NULL);
    MVET_ASSERT(buffer != NULL || header.length == 0);

    json->buffer = buffer;
    /* The cursor produced this span, so offset + length cannot wrap. */
    json->index = header.offset;
    json->end = header.offset + header.length;
    json->report = report;
    MVET_ASSERT(json->index <= json->end);
}

void mvet_st_json_skip_ws(mvet_st_json_t *json)
{
    MVET_ASSERT(json != NULL);

    while (json->index < json->end && mvet_st_json_is_ws(json->buffer[json->index]))
        json->index++;
}

bool mvet_st_json_at_end(const mvet_st_json_t *json)
{
    MVET_ASSERT(json != NULL);

    return json->index == json->end;
}

mvet_istatus_t mvet_st_json_peek(const mvet_st_json_t *json, uint8_t *byte)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(byte != NULL);

    if (json->index >= json->end)
        return mvet_st_json_reject_here(json);
    *byte = json->buffer[json->index];
    return MVET_I_OK;
}

mvet_istatus_t mvet_st_json_expect(mvet_st_json_t *json, uint8_t token)
{
    MVET_ASSERT(json != NULL);

    if (json->index >= json->end || json->buffer[json->index] != token)
        return mvet_st_json_reject_here(json);
    json->index++;
    return MVET_I_OK;
}

mvet_istatus_t mvet_st_json_reject_here(const mvet_st_json_t *json)
{
    MVET_ASSERT(json != NULL);

    uint64_t observed = json->index < json->end ? (uint64_t)json->buffer[json->index] : 0u;
    mvet_issue_t issue = mvet_issue_make(MVET_V_ST_JSON_SYNTAX, (uint64_t)json->index, observed, 0);
    return mvet_violation(json->report, issue);
}

mvet_istatus_t mvet_st_json_read_key(mvet_st_json_t *json, mvet_span_t *span)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(span != NULL);

    MVET_TRY(mvet_st_json_scan_string(json, span, false));
    if (span->length > (size_t)MVET_MAX_ST_NAME_BYTES) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_NAME_LEN,
                                             (uint64_t)span->offset,
                                             (uint64_t)span->length,
                                             MVET_MAX_ST_NAME_BYTES);
        return mvet_violation(json->report, issue);
    }
    return mvet_st_json_check_utf8(json, *span);
}

mvet_istatus_t mvet_st_json_read_string(mvet_st_json_t *json, mvet_span_t *span)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(span != NULL);

    MVET_TRY(mvet_st_json_scan_string(json, span, true));
    return mvet_st_json_check_utf8(json, *span);
}

mvet_istatus_t mvet_st_json_read_u64(mvet_st_json_t *json, uint64_t *value)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(value != NULL);

    size_t number_index = json->index;
    if (json->index >= json->end || !mvet_st_json_is_digit(json->buffer[json->index]))
        return mvet_st_json_reject_number(json, number_index);

    uint64_t accumulated = 0;
    if (json->buffer[json->index] == '0')
        json->index++;
    else
        MVET_TRY(mvet_st_json_read_digits(json, &accumulated, number_index));

    /* A digit here is a leading zero; a tail byte is a float. */
    if (json->index < json->end) {
        uint8_t next = json->buffer[json->index];
        if (mvet_st_json_is_digit(next) || mvet_st_json_is_number_tail(next))
            return mvet_st_json_reject_number(json, number_index);
    }
    *value = accumulated;
    return MVET_I_OK;
}

mvet_istatus_t
mvet_st_json_open_sequence(mvet_st_json_t *json, uint8_t open, uint8_t close, bool *empty)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(empty != NULL);

    MVET_TRY(mvet_st_json_expect(json, open));
    mvet_st_json_skip_ws(json);
    uint8_t next = 0;
    MVET_TRY(mvet_st_json_peek(json, &next));
    if (next == close) {
        *empty = true;
        return mvet_st_json_expect(json, close);
    }
    *empty = false;
    return MVET_I_OK;
}

mvet_istatus_t mvet_st_json_continue_sequence(mvet_st_json_t *json, uint8_t close, bool *closed)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(closed != NULL);

    mvet_st_json_skip_ws(json);
    uint8_t next = 0;
    MVET_TRY(mvet_st_json_peek(json, &next));
    if (next == close) {
        *closed = true;
        return mvet_st_json_expect(json, close);
    }
    if (next != ',')
        return mvet_st_json_reject_here(json);
    MVET_TRY(mvet_st_json_expect(json, ','));
    mvet_st_json_skip_ws(json);
    *closed = false;
    return MVET_I_OK;
}

bool mvet_st_json_span_is(const mvet_st_json_t *json,
                          mvet_span_t span,
                          const char *literal,
                          size_t literal_length)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(literal != NULL);

    if (span.length != literal_length)
        return false;
    for (size_t byte_index = 0; byte_index < literal_length; byte_index++) {
        if (json->buffer[span.offset + byte_index] != (uint8_t)literal[byte_index])
            return false;
    }
    return true;
}

static bool mvet_st_json_is_ws(uint8_t byte)
{
    return byte == ' ' || byte == '\t' || byte == '\n' || byte == '\r';
}

static mvet_istatus_t
mvet_st_json_scan_string(mvet_st_json_t *json, mvet_span_t *span, bool allow_escapes)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(span != NULL);

    MVET_TRY(mvet_st_json_expect(json, '"'));
    size_t content_start = json->index;
    while (json->index < json->end) {
        if (json->buffer[json->index] == '"') {
            *span = (mvet_span_t){
                .offset = content_start,
                .length = json->index - content_start,
            };
            json->index++;
            return MVET_I_OK;
        }
        MVET_TRY(mvet_st_json_scan_content_byte(json, allow_escapes));
    }
    return mvet_st_json_reject_here(json);
}

static mvet_istatus_t mvet_st_json_scan_content_byte(mvet_st_json_t *json, bool allow_escapes)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(json->index < json->end);

    uint8_t byte = json->buffer[json->index];
    if (byte == '\\')
        return mvet_st_json_scan_escape(json, allow_escapes);
    if (byte < MVET_ST_JSON_CONTROL_LIMIT)
        return mvet_st_json_reject_here(json);
    json->index++;
    return MVET_I_OK;
}

static mvet_istatus_t mvet_st_json_scan_escape(mvet_st_json_t *json, bool allow_escapes)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(json->index < json->end);
    MVET_ASSERT(json->buffer[json->index] == '\\');

    size_t backslash_index = json->index;
    if (!allow_escapes) {
        size_t designator_index = backslash_index + 1u;
        uint64_t designator =
            designator_index < json->end ? (uint64_t)json->buffer[designator_index] : 0u;
        mvet_issue_t issue =
            mvet_issue_make(MVET_V_ST_KEY_ESCAPE, (uint64_t)backslash_index, designator, 0);
        return mvet_violation(json->report, issue);
    }
    json->index++;
    return mvet_st_json_check_escape(json, backslash_index);
}

static mvet_istatus_t mvet_st_json_check_escape(mvet_st_json_t *json, size_t backslash_index)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(backslash_index < json->index);

    if (json->index >= json->end)
        return mvet_st_json_reject_escape(json, backslash_index);
    uint8_t designator = json->buffer[json->index];
    json->index++;
    if (mvet_st_json_is_simple_escape(designator))
        return MVET_I_OK;
    if (designator != 'u')
        return mvet_st_json_reject_escape(json, backslash_index);
    return mvet_st_json_check_unicode_escape(json, backslash_index);
}

static bool mvet_st_json_is_simple_escape(uint8_t designator)
{
    return designator == '"' || designator == '\\' || designator == '/' || designator == 'b' ||
           designator == 'f' || designator == 'n' || designator == 'r' || designator == 't';
}

static mvet_istatus_t mvet_st_json_check_unicode_escape(mvet_st_json_t *json,
                                                        size_t backslash_index)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(backslash_index < json->index);

    uint32_t unit = 0;
    if (!mvet_st_json_read_hex4(json, &unit))
        return mvet_st_json_reject_escape(json, backslash_index);
    if (unit >= MVET_ST_JSON_SURROGATE_LOW_FIRST && unit <= MVET_ST_JSON_SURROGATE_LOW_LAST)
        return mvet_st_json_reject_escape(json, backslash_index);
    if (unit < MVET_ST_JSON_SURROGATE_HIGH_FIRST || unit > MVET_ST_JSON_SURROGATE_HIGH_LAST)
        return MVET_I_OK;

    /* A high surrogate requires an immediately following low escape. */
    if (json->index >= json->end || json->buffer[json->index] != '\\')
        return mvet_st_json_reject_escape(json, backslash_index);
    json->index++;
    if (json->index >= json->end || json->buffer[json->index] != 'u')
        return mvet_st_json_reject_escape(json, backslash_index);
    json->index++;
    uint32_t low_unit = 0;
    if (!mvet_st_json_read_hex4(json, &low_unit))
        return mvet_st_json_reject_escape(json, backslash_index);
    if (low_unit < MVET_ST_JSON_SURROGATE_LOW_FIRST || low_unit > MVET_ST_JSON_SURROGATE_LOW_LAST)
        return mvet_st_json_reject_escape(json, backslash_index);
    return MVET_I_OK;
}

static bool mvet_st_json_read_hex4(mvet_st_json_t *json, uint32_t *value)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(value != NULL);

    uint32_t accumulated = 0;
    for (size_t digit_index = 0; digit_index < MVET_ST_JSON_HEX_DIGITS; digit_index++) {
        if (json->index >= json->end)
            return false;
        uint32_t nibble = 0;
        if (!mvet_st_json_hex_value(json->buffer[json->index], &nibble))
            return false;
        /* Four nibbles keep the accumulator under 2^16: no overflow. */
        accumulated = accumulated * MVET_ST_JSON_HEX_BASE + nibble;
        json->index++;
    }
    *value = accumulated;
    return true;
}

static bool mvet_st_json_hex_value(uint8_t byte, uint32_t *value)
{
    MVET_ASSERT(value != NULL);

    if (byte >= '0' && byte <= '9') {
        *value = (uint32_t)(byte - '0');
        return true;
    }
    if (byte >= 'a' && byte <= 'f') {
        *value = (uint32_t)(byte - 'a') + MVET_ST_JSON_DECIMAL_BASE;
        return true;
    }
    if (byte >= 'A' && byte <= 'F') {
        *value = (uint32_t)(byte - 'A') + MVET_ST_JSON_DECIMAL_BASE;
        return true;
    }
    return false;
}

static mvet_istatus_t mvet_st_json_reject_escape(const mvet_st_json_t *json, size_t backslash_index)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(backslash_index < json->end);

    size_t designator_index = backslash_index + 1u;
    uint64_t designator =
        designator_index < json->end ? (uint64_t)json->buffer[designator_index] : 0u;
    mvet_issue_t issue =
        mvet_issue_make(MVET_V_ST_STR_ESCAPE, (uint64_t)backslash_index, designator, 0);
    return mvet_violation(json->report, issue);
}

static mvet_istatus_t mvet_st_json_check_utf8(const mvet_st_json_t *json, mvet_span_t span)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(span.offset + span.length <= json->end);

    uint64_t bad_index = 0;
    if (mvet_utf8_is_valid(json->buffer + span.offset, (uint64_t)span.length, &bad_index))
        return MVET_I_OK;
    mvet_issue_t issue =
        mvet_issue_make(MVET_V_ST_STR_UTF8, (uint64_t)span.offset + bad_index, bad_index, 0);
    return mvet_violation(json->report, issue);
}

static bool mvet_st_json_is_digit(uint8_t byte)
{
    return byte >= '0' && byte <= '9';
}

static bool mvet_st_json_is_number_tail(uint8_t byte)
{
    return byte == '.' || byte == 'e' || byte == 'E';
}

static mvet_istatus_t mvet_st_json_reject_number(const mvet_st_json_t *json, size_t number_index)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(number_index <= json->index);

    mvet_issue_t issue = mvet_issue_make(MVET_V_ST_NUMBER, (uint64_t)number_index, 0, 0);
    return mvet_violation(json->report, issue);
}

static mvet_istatus_t
mvet_st_json_read_digits(mvet_st_json_t *json, uint64_t *accumulated, size_t number_index)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(accumulated != NULL);

    while (json->index < json->end && mvet_st_json_is_digit(json->buffer[json->index])) {
        uint64_t digit = (uint64_t)(json->buffer[json->index] - '0');
        bool scaled = mvet_checked_mul_u64(accumulated, *accumulated, MVET_ST_JSON_DECIMAL_BASE);
        if (!scaled || !mvet_checked_add_u64(accumulated, *accumulated, digit))
            return mvet_st_json_reject_number(json, number_index);
        json->index++;
    }
    return MVET_I_OK;
}
/* ---- src/st_tensors.c ---- */
/* st_tensors.c: owns tensor-entry validation, the pinned dtype table,
 * byte-size accounting, and the sorted-extent layout checks.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>


enum {
    MVET_ST_DTYPE_COUNT = 22,
    MVET_ST_FIELD_DTYPE = 1,
    MVET_ST_FIELD_SHAPE = 2,
    MVET_ST_FIELD_OFFSETS = 4,
    MVET_ST_FIELDS_REQUIRED = 7,
    /* Three known fields; a fourth key is always a FIELDS violation. */
    MVET_ST_TENSOR_FIELD_LIMIT = 5,
    MVET_ST_BITS_PER_BYTE = 8,
    MVET_ST_HEAP_ARITY = 2
};

/* Each explicit dimension spends at least two header bytes. */
#define MVET_ST_SHAPE_DIM_LIMIT ((size_t)MVET_MAX_ST_HEADER_BYTES / 2u + 2u)

/* One dtype row: name bytes and the per-element bit width. */
typedef struct {
    const char *name;
    uint8_t name_length;
    uint8_t bits;
} mvet_st_dtype_t;

/* Verified against the exact commit in tools/st-pin.env. */
static const mvet_st_dtype_t mvet_st_dtype_table[MVET_ST_DTYPE_COUNT] = {
    {.name = "F4", .name_length = 2, .bits = 4},
    {.name = "F6_E2M3", .name_length = 7, .bits = 6},
    {.name = "F6_E3M2", .name_length = 7, .bits = 6},
    {.name = "BOOL", .name_length = 4, .bits = 8},
    {.name = "U8", .name_length = 2, .bits = 8},
    {.name = "I8", .name_length = 2, .bits = 8},
    {.name = "F8_E5M2", .name_length = 7, .bits = 8},
    {.name = "F8_E4M3", .name_length = 7, .bits = 8},
    {.name = "F8_E8M0", .name_length = 7, .bits = 8},
    {.name = "F8_E4M3FNUZ", .name_length = 11, .bits = 8},
    {.name = "F8_E5M2FNUZ", .name_length = 11, .bits = 8},
    {.name = "I16", .name_length = 3, .bits = 16},
    {.name = "U16", .name_length = 3, .bits = 16},
    {.name = "F16", .name_length = 3, .bits = 16},
    {.name = "BF16", .name_length = 4, .bits = 16},
    {.name = "I32", .name_length = 3, .bits = 32},
    {.name = "U32", .name_length = 3, .bits = 32},
    {.name = "F32", .name_length = 3, .bits = 32},
    {.name = "I64", .name_length = 3, .bits = 64},
    {.name = "U64", .name_length = 3, .bits = 64},
    {.name = "F64", .name_length = 3, .bits = 64},
    {.name = "C64", .name_length = 3, .bits = 64},
};

/* One tensor entry mid-parse. element_product, dtype_bits, and the
 * begin/end pair are valid once their seen_mask bits are set. */
typedef struct {
    uint64_t element_product;
    uint64_t begin;
    uint64_t end;
    uint32_t dtype_bits;
    uint32_t seen_mask;
    size_t shape_offset;
    size_t offsets_offset;
} mvet_st_record_t;

/* Walks one tensor object into the record, requiring exactly the three
 * known fields. */
static mvet_istatus_t mvet_st_read_tensor_object(mvet_st_json_t *json, mvet_st_record_t *record);

/* Reads one field: key, colon, and the value for that field kind. */
static mvet_istatus_t mvet_st_read_field(mvet_st_json_t *json, mvet_st_record_t *record);

/* Reads one field, then the separator after it. */
static mvet_istatus_t
mvet_st_read_field_step(mvet_st_json_t *json, mvet_st_record_t *record, bool *closed);

/* Claims the field named by key once, then reads its value. */
static mvet_istatus_t
mvet_st_dispatch_field(mvet_st_json_t *json, mvet_st_record_t *record, mvet_span_t key);

/* Maps a key span to its field bit; zero for an unknown key. Pure. */
static uint32_t mvet_st_field_bit(const mvet_st_json_t *json, mvet_span_t key);

/* Reads the dtype string. Sole producer for an unknown dtype name. */
static mvet_istatus_t mvet_st_read_dtype(mvet_st_json_t *json, mvet_st_record_t *record);

/* Writes the bit width for a dtype name span. False when absent. Pure. */
static bool mvet_st_find_dtype(const mvet_st_json_t *json, mvet_span_t name, uint32_t *bits);

/* Reads the shape array into a checked element product. */
static mvet_istatus_t mvet_st_read_shape(mvet_st_json_t *json, mvet_st_record_t *record);

/* Folds one dimension into the product, then the separator after it. */
static mvet_istatus_t
mvet_st_read_shape_dimension(mvet_st_json_t *json, mvet_st_record_t *record, bool *closed);

/* Reads the two-element data_offsets array. */
static mvet_istatus_t mvet_st_read_offsets(mvet_st_json_t *json, mvet_st_record_t *record);

/* Reads the closing offset bound and requires the array to end. */
static mvet_istatus_t
mvet_st_read_offsets_end(mvet_st_json_t *json, mvet_st_record_t *record, size_t array_offset);

/* Sole producer for a data_offsets arity other than two. */
static mvet_istatus_t mvet_st_reject_arity(const mvet_st_json_t *json, size_t offset, uint64_t got);

/* Requires the complete field set at the object close. */
static mvet_istatus_t mvet_st_check_required(mvet_st_json_t *json, const mvet_st_record_t *record);

/* Sole producer for a wrong tensor field set. */
static mvet_istatus_t
mvet_st_reject_fields(const mvet_st_json_t *json, size_t offset, uint32_t seen_mask);

/* Derives the exact byte count from shape and dtype. Violations:
 * size overflow, sub-byte misalignment. */
static mvet_istatus_t
mvet_st_check_size(mvet_st_json_t *json, const mvet_st_record_t *record, uint64_t *expected_bytes);

/* Sole producer for overflowing size arithmetic. */
static mvet_istatus_t
mvet_st_reject_size(const mvet_st_json_t *json, size_t offset, uint64_t left, uint64_t right);

/* Requires a forward offset pair spanning exactly expected_bytes.
 * Violations: offset order, size mismatch. */
static mvet_istatus_t mvet_st_check_offsets(mvet_st_json_t *json,
                                            const mvet_st_record_t *record,
                                            uint64_t expected_bytes);

/* Stores one validated extent. Infallible; the carve bound admits it. */
static void mvet_st_record_extent(mvet_st_t *context, const mvet_st_record_t *record);

/* Data-region start, the governing boundary for layout reports. Pure. */
static size_t mvet_st_data_region_start(const mvet_st_t *context);

/* Sorts extents by (begin, end). Iterative heapsort: no recursion, no
 * allocation, deterministic. */
static void mvet_st_extent_sort(mvet_st_extent_t *extents, size_t count);

/* Restores the max-heap below root in a bounded extent prefix. */
static void mvet_st_extent_sift_down(mvet_st_extent_t *extents, size_t count, size_t root);

/* True when left orders strictly before right by (begin, end). Pure. */
static bool mvet_st_extent_less(mvet_st_extent_t left, mvet_st_extent_t right);

/* Exchanges two extent values. */
static void mvet_st_extent_swap(mvet_st_extent_t *left, mvet_st_extent_t *right);

mvet_istatus_t mvet_st_tensor_entry(mvet_st_t *context, mvet_st_json_t *json)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(json != NULL);

    if (context->tensor_count >= (size_t)MVET_MAX_ST_TENSORS) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_TENSOR_COUNT_CAP,
                                             (uint64_t)json->index,
                                             (uint64_t)context->tensor_count + 1u,
                                             MVET_MAX_ST_TENSORS);
        return mvet_violation(json->report, issue);
    }

    mvet_st_record_t record = {0};
    MVET_TRY(mvet_st_read_tensor_object(json, &record));

    uint64_t expected_bytes = 0;
    MVET_TRY(mvet_st_check_size(json, &record, &expected_bytes));
    MVET_TRY(mvet_st_check_offsets(json, &record, expected_bytes));
    mvet_st_record_extent(context, &record);
    return MVET_I_OK;
}

mvet_istatus_t mvet_st_layout_pass(mvet_st_t *context)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(context->tensor_count <= context->extent_bound);

    mvet_st_extent_sort(context->extents, context->tensor_count);

    uint64_t running_end = 0;
    for (size_t extent_index = 0; extent_index < context->tensor_count; extent_index++) {
        mvet_st_extent_t extent = context->extents[extent_index];
        MVET_ASSERT(extent.end >= extent.begin);
        if (extent.begin != running_end) {
            mvet_issue_t issue = mvet_issue_make(MVET_V_ST_OFFSET_CONTIGUITY,
                                                 (uint64_t)mvet_st_data_region_start(context),
                                                 extent.begin,
                                                 running_end);
            return mvet_violation(context->cursor.report, issue);
        }
        running_end = extent.end;
    }

    if (running_end != context->data_region_bytes) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_DATA_EXTENT,
                                             (uint64_t)mvet_st_data_region_start(context),
                                             running_end,
                                             context->data_region_bytes);
        return mvet_violation(context->cursor.report, issue);
    }
    return MVET_I_OK;
}

static mvet_istatus_t mvet_st_read_tensor_object(mvet_st_json_t *json, mvet_st_record_t *record)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    bool empty = false;
    MVET_TRY(mvet_st_json_open_sequence(json, '{', '}', &empty));
    if (empty)
        return mvet_st_check_required(json, record);

    for (size_t field = 0; field < (size_t)MVET_ST_TENSOR_FIELD_LIMIT; field++) {
        bool closed = false;
        MVET_TRY(mvet_st_read_field_step(json, record, &closed));
        if (closed)
            return mvet_st_check_required(json, record);
    }
    /* Unreachable: a fourth key always rejects inside the loop above.
     * Fail closed rather than assert against a hostile input. */
    return mvet_st_json_reject_here(json);
}

static mvet_istatus_t
mvet_st_read_field_step(mvet_st_json_t *json, mvet_st_record_t *record, bool *closed)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(closed != NULL);

    MVET_TRY(mvet_st_read_field(json, record));
    return mvet_st_json_continue_sequence(json, '}', closed);
}

static mvet_istatus_t mvet_st_read_field(mvet_st_json_t *json, mvet_st_record_t *record)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    mvet_span_t key = {0};
    MVET_TRY(mvet_st_json_read_key(json, &key));
    mvet_st_json_skip_ws(json);
    MVET_TRY(mvet_st_json_expect(json, ':'));
    mvet_st_json_skip_ws(json);
    return mvet_st_dispatch_field(json, record, key);
}

static mvet_istatus_t
mvet_st_dispatch_field(mvet_st_json_t *json, mvet_st_record_t *record, mvet_span_t key)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    /* Unknown-field rejection is policy: the canonical reader ignores
     * unknown tensor fields; repeats it rejects, mirrored here. */
    uint32_t field_bit = mvet_st_field_bit(json, key);
    if (field_bit == 0 || (record->seen_mask & field_bit) != 0)
        return mvet_st_reject_fields(json, key.offset, record->seen_mask);
    record->seen_mask |= field_bit;

    if (field_bit == MVET_ST_FIELD_DTYPE)
        return mvet_st_read_dtype(json, record);
    if (field_bit == MVET_ST_FIELD_SHAPE) {
        record->shape_offset = json->index;
        return mvet_st_read_shape(json, record);
    }
    record->offsets_offset = json->index;
    return mvet_st_read_offsets(json, record);
}

static uint32_t mvet_st_field_bit(const mvet_st_json_t *json, mvet_span_t key)
{
    MVET_ASSERT(json != NULL);

    if (mvet_st_json_span_is(json, key, "dtype", 5))
        return MVET_ST_FIELD_DTYPE;
    if (mvet_st_json_span_is(json, key, "shape", 5))
        return MVET_ST_FIELD_SHAPE;
    if (mvet_st_json_span_is(json, key, "data_offsets", 12))
        return MVET_ST_FIELD_OFFSETS;
    return 0;
}

static mvet_istatus_t mvet_st_read_dtype(mvet_st_json_t *json, mvet_st_record_t *record)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    size_t value_offset = json->index;
    mvet_span_t name = {0};
    MVET_TRY(mvet_st_json_read_string(json, &name));

    uint32_t bits = 0;
    if (!mvet_st_find_dtype(json, name, &bits)) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_DTYPE_UNKNOWN, (uint64_t)value_offset, 0, 0);
        return mvet_violation(json->report, issue);
    }
    record->dtype_bits = bits;
    return MVET_I_OK;
}

static bool mvet_st_find_dtype(const mvet_st_json_t *json, mvet_span_t name, uint32_t *bits)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(bits != NULL);

    for (size_t row_index = 0; row_index < (size_t)MVET_ST_DTYPE_COUNT; row_index++) {
        mvet_st_dtype_t row = mvet_st_dtype_table[row_index];
        if (mvet_st_json_span_is(json, name, row.name, row.name_length)) {
            *bits = row.bits;
            return true;
        }
    }
    return false;
}

static mvet_istatus_t mvet_st_read_shape(mvet_st_json_t *json, mvet_st_record_t *record)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    record->element_product = 1;
    bool empty = false;
    MVET_TRY(mvet_st_json_open_sequence(json, '[', ']', &empty));
    if (empty)
        return MVET_I_OK;

    for (size_t dimension_index = 0; dimension_index < MVET_ST_SHAPE_DIM_LIMIT; dimension_index++) {
        bool closed = false;
        MVET_TRY(mvet_st_read_shape_dimension(json, record, &closed));
        if (closed)
            return MVET_I_OK;
    }
    /* Unreachable: every dimension consumes at least two header bytes.
     * Fail closed rather than assert against a hostile input. */
    return mvet_st_json_reject_here(json);
}

static mvet_istatus_t
mvet_st_read_shape_dimension(mvet_st_json_t *json, mvet_st_record_t *record, bool *closed)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(closed != NULL);

    size_t number_offset = json->index;
    uint64_t dimension = 0;
    MVET_TRY(mvet_st_json_read_u64(json, &dimension));
    bool product_fits =
        mvet_checked_mul_u64(&record->element_product, record->element_product, dimension);
    if (!product_fits)
        return mvet_st_reject_size(json, number_offset, record->element_product, dimension);
    return mvet_st_json_continue_sequence(json, ']', closed);
}

static mvet_istatus_t mvet_st_read_offsets(mvet_st_json_t *json, mvet_st_record_t *record)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    size_t array_offset = record->offsets_offset;
    bool empty = false;
    MVET_TRY(mvet_st_json_open_sequence(json, '[', ']', &empty));
    if (empty)
        return mvet_st_reject_arity(json, array_offset, 0);

    bool closed = false;
    MVET_TRY(mvet_st_json_read_u64(json, &record->begin));
    MVET_TRY(mvet_st_json_continue_sequence(json, ']', &closed));
    if (closed)
        return mvet_st_reject_arity(json, array_offset, 1);
    return mvet_st_read_offsets_end(json, record, array_offset);
}

static mvet_istatus_t
mvet_st_read_offsets_end(mvet_st_json_t *json, mvet_st_record_t *record, size_t array_offset)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    MVET_TRY(mvet_st_json_read_u64(json, &record->end));
    mvet_st_json_skip_ws(json);
    uint8_t next = 0;
    MVET_TRY(mvet_st_json_peek(json, &next));
    if (next == ',')
        return mvet_st_reject_arity(json, array_offset, 3);
    return mvet_st_json_expect(json, ']');
}

static mvet_istatus_t mvet_st_reject_arity(const mvet_st_json_t *json, size_t offset, uint64_t got)
{
    MVET_ASSERT(json != NULL);

    mvet_issue_t issue = mvet_issue_make(MVET_V_ST_OFFSETS_ARITY, (uint64_t)offset, got, 2);
    return mvet_violation(json->report, issue);
}

static mvet_istatus_t mvet_st_check_required(mvet_st_json_t *json, const mvet_st_record_t *record)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(json->index > 0);

    if (record->seen_mask == MVET_ST_FIELDS_REQUIRED)
        return MVET_I_OK;
    /* The closing brace was just consumed; report at it. */
    return mvet_st_reject_fields(json, json->index - 1u, record->seen_mask);
}

static mvet_istatus_t
mvet_st_reject_fields(const mvet_st_json_t *json, size_t offset, uint32_t seen_mask)
{
    MVET_ASSERT(json != NULL);

    mvet_issue_t issue = mvet_issue_make(
        MVET_V_ST_TENSOR_FIELDS, (uint64_t)offset, seen_mask, MVET_ST_FIELDS_REQUIRED);
    return mvet_violation(json->report, issue);
}

static mvet_istatus_t
mvet_st_check_size(mvet_st_json_t *json, const mvet_st_record_t *record, uint64_t *expected_bytes)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(expected_bytes != NULL);
    MVET_ASSERT(record->dtype_bits != 0);

    uint64_t total_bits = 0;
    bool bits_fit =
        mvet_checked_mul_u64(&total_bits, record->element_product, (uint64_t)record->dtype_bits);
    if (!bits_fit) {
        return mvet_st_reject_size(
            json, record->shape_offset, record->element_product, record->dtype_bits);
    }
    if (total_bits % MVET_ST_BITS_PER_BYTE != 0) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_SIZE_MISALIGNED,
                                             (uint64_t)record->shape_offset,
                                             total_bits,
                                             MVET_ST_BITS_PER_BYTE);
        return mvet_violation(json->report, issue);
    }
    *expected_bytes = total_bits / MVET_ST_BITS_PER_BYTE;
    return MVET_I_OK;
}

static mvet_istatus_t
mvet_st_reject_size(const mvet_st_json_t *json, size_t offset, uint64_t left, uint64_t right)
{
    MVET_ASSERT(json != NULL);

    mvet_issue_t issue = mvet_issue_make(MVET_V_ST_SIZE_OVERFLOW, (uint64_t)offset, left, right);
    return mvet_violation(json->report, issue);
}

static mvet_istatus_t
mvet_st_check_offsets(mvet_st_json_t *json, const mvet_st_record_t *record, uint64_t expected_bytes)
{
    MVET_ASSERT(json != NULL);
    MVET_ASSERT(record != NULL);

    if (record->end < record->begin) {
        mvet_issue_t issue = mvet_issue_make(
            MVET_V_ST_OFFSET_ORDER, (uint64_t)record->offsets_offset, record->begin, record->end);
        return mvet_violation(json->report, issue);
    }

    /* Licensed by the order check above: end - begin cannot wrap. */
    uint64_t declared_bytes = record->end - record->begin;
    if (declared_bytes != expected_bytes) {
        mvet_issue_t issue = mvet_issue_make(MVET_V_ST_SIZE_MISMATCH,
                                             (uint64_t)record->offsets_offset,
                                             declared_bytes,
                                             expected_bytes);
        return mvet_violation(json->report, issue);
    }
    return MVET_I_OK;
}

static void mvet_st_record_extent(mvet_st_t *context, const mvet_st_record_t *record)
{
    MVET_ASSERT(context != NULL);
    MVET_ASSERT(record != NULL);
    MVET_ASSERT(record->seen_mask == MVET_ST_FIELDS_REQUIRED);
    /* Every tensor entry spends at least MVET_ST_MIN_TENSOR_ENTRY_BYTES
     * header bytes, so the carve bound strictly exceeds the count. */
    MVET_ASSERT(context->tensor_count < context->extent_bound);

    context->extents[context->tensor_count] = (mvet_st_extent_t){
        .begin = record->begin,
        .end = record->end,
    };
    context->tensor_count++;
}

static size_t mvet_st_data_region_start(const mvet_st_t *context)
{
    MVET_ASSERT(context != NULL);

    /* The cursor produced the header span: this sum cannot wrap. */
    return context->header.offset + context->header.length;
}

static void mvet_st_extent_sort(mvet_st_extent_t *extents, size_t count)
{
    MVET_ASSERT(extents != NULL || count == 0);

    if (count < MVET_ST_HEAP_ARITY)
        return;
    for (size_t start = count / MVET_ST_HEAP_ARITY; start > 0; start--)
        mvet_st_extent_sift_down(extents, count, start - 1u);
    for (size_t end = count - 1u; end > 0; end--) {
        mvet_st_extent_swap(&extents[0], &extents[end]);
        mvet_st_extent_sift_down(extents, end, 0);
    }
}

static void mvet_st_extent_sift_down(mvet_st_extent_t *extents, size_t count, size_t root)
{
    MVET_ASSERT(extents != NULL);
    MVET_ASSERT(root < count);

    while (root < count / MVET_ST_HEAP_ARITY) {
        size_t child = root * MVET_ST_HEAP_ARITY + 1u;
        if (child + 1u < count && mvet_st_extent_less(extents[child], extents[child + 1u]))
            child++;
        if (!mvet_st_extent_less(extents[root], extents[child]))
            return;
        mvet_st_extent_swap(&extents[root], &extents[child]);
        root = child;
    }
}

static bool mvet_st_extent_less(mvet_st_extent_t left, mvet_st_extent_t right)
{
    if (left.begin != right.begin)
        return left.begin < right.begin;
    return left.end < right.end;
}

static void mvet_st_extent_swap(mvet_st_extent_t *left, mvet_st_extent_t *right)
{
    MVET_ASSERT(left != NULL);
    MVET_ASSERT(right != NULL);

    mvet_st_extent_t held = *left;
    *left = *right;
    *right = held;
}
/* ---- src/utf8.c ---- */
/* utf8.c: owns strict UTF-8 validation as a table-driven state machine
 * over byte classes (Hoehrmann-style, written fresh for this project).
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdbool.h>
#include <stdint.h>


/* Byte-range boundaries of the UTF-8 encoding, inclusive. */
enum {
    MVET_UTF8_ASCII_MAX = 0x7f,
    MVET_UTF8_CONT_LOW_MAX = 0x8f,  /* continuations 0x80-0x8f */
    MVET_UTF8_CONT_MID_MAX = 0x9f,  /* continuations 0x90-0x9f */
    MVET_UTF8_CONT_HIGH_MAX = 0xbf, /* continuations 0xa0-0xbf */
    MVET_UTF8_OVERLONG2_MAX = 0xc1, /* 0xc0-0xc1: always overlong */
    MVET_UTF8_LEAD2_MAX = 0xdf,
    MVET_UTF8_LEAD3_E0 = 0xe0, /* second byte must be 0xa0-0xbf */
    MVET_UTF8_LEAD3_ED = 0xed, /* second byte must be 0x80-0x9f */
    MVET_UTF8_LEAD3_MAX = 0xef,
    MVET_UTF8_LEAD4_F0 = 0xf0, /* second byte must be 0x90-0xbf */
    MVET_UTF8_LEAD4_F4 = 0xf4  /* second byte must be 0x80-0x8f */
};

/* Character classes: the three continuation sub-ranges stay distinct
 * because the constrained leads (E0/ED/F0/F4) accept different subsets. */
typedef enum {
    MVET_U8C_ASCII = 0,
    MVET_U8C_CONT_LOW,
    MVET_U8C_CONT_MID,
    MVET_U8C_CONT_HIGH,
    MVET_U8C_LEAD2,
    MVET_U8C_LEAD3_E0,
    MVET_U8C_LEAD3,
    MVET_U8C_LEAD3_ED,
    MVET_U8C_LEAD4_F0,
    MVET_U8C_LEAD4,
    MVET_U8C_LEAD4_F4,
    MVET_U8C_ILLEGAL,
    MVET_U8C_COUNT
} mvet_utf8_class_t;

/* States: TAILn expects n unconstrained continuations; the four PEND
 * states expect one constrained continuation first. */
typedef enum {
    MVET_U8S_ACCEPT = 0,
    MVET_U8S_TAIL1,
    MVET_U8S_TAIL2,
    MVET_U8S_TAIL3,
    MVET_U8S_E0_PEND,
    MVET_U8S_ED_PEND,
    MVET_U8S_F0_PEND,
    MVET_U8S_F4_PEND,
    MVET_U8S_REJECT,
    MVET_U8S_COUNT
} mvet_utf8_state_t;

/* Classifies one byte into its UTF-8 character class. Pure. */
static uint8_t mvet_utf8_classify(uint8_t byte);

/* Transition table, indexed [state][class]. Rows follow the state enum;
 * columns follow the class enum. The REJECT row is never stepped (the
 * scan stops on entering REJECT) but keeps the table total. */
static const uint8_t mvet_utf8_step[MVET_U8S_COUNT][MVET_U8C_COUNT] = {
    [MVET_U8S_ACCEPT] = {MVET_U8S_ACCEPT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_TAIL1,
                         MVET_U8S_E0_PEND,
                         MVET_U8S_TAIL2,
                         MVET_U8S_ED_PEND,
                         MVET_U8S_F0_PEND,
                         MVET_U8S_TAIL3,
                         MVET_U8S_F4_PEND,
                         MVET_U8S_REJECT},
    [MVET_U8S_TAIL1] = {MVET_U8S_REJECT,
                        MVET_U8S_ACCEPT,
                        MVET_U8S_ACCEPT,
                        MVET_U8S_ACCEPT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT},
    [MVET_U8S_TAIL2] = {MVET_U8S_REJECT,
                        MVET_U8S_TAIL1,
                        MVET_U8S_TAIL1,
                        MVET_U8S_TAIL1,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT},
    [MVET_U8S_TAIL3] = {MVET_U8S_REJECT,
                        MVET_U8S_TAIL2,
                        MVET_U8S_TAIL2,
                        MVET_U8S_TAIL2,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT,
                        MVET_U8S_REJECT},
    [MVET_U8S_E0_PEND] = {MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_TAIL1,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT},
    [MVET_U8S_ED_PEND] = {MVET_U8S_REJECT,
                          MVET_U8S_TAIL1,
                          MVET_U8S_TAIL1,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT},
    [MVET_U8S_F0_PEND] = {MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_TAIL2,
                          MVET_U8S_TAIL2,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT},
    [MVET_U8S_F4_PEND] = {MVET_U8S_REJECT,
                          MVET_U8S_TAIL2,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT,
                          MVET_U8S_REJECT},
    [MVET_U8S_REJECT] = {MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT,
                         MVET_U8S_REJECT},
};

bool mvet_utf8_is_valid(const uint8_t *bytes, uint64_t length, uint64_t *bad_index)
{
    MVET_ASSERT(bad_index != NULL);
    MVET_ASSERT(bytes != NULL || length == 0);

    uint8_t state = MVET_U8S_ACCEPT;
    MVET_WORK_ADD(length + 1u);
    for (uint64_t byte_index = 0; byte_index < length; byte_index++) {
        state = mvet_utf8_step[state][mvet_utf8_classify(bytes[byte_index])];
        if (state == MVET_U8S_REJECT) {
            *bad_index = byte_index;
            return false;
        }
    }
    if (state != MVET_U8S_ACCEPT) {
        *bad_index = length; /* input ended inside a multi-byte sequence */
        return false;
    }
    return true;
}

static uint8_t mvet_utf8_classify(uint8_t byte)
{
    if (byte <= MVET_UTF8_ASCII_MAX)
        return MVET_U8C_ASCII;
    if (byte <= MVET_UTF8_CONT_LOW_MAX)
        return MVET_U8C_CONT_LOW;
    if (byte <= MVET_UTF8_CONT_MID_MAX)
        return MVET_U8C_CONT_MID;
    if (byte <= MVET_UTF8_CONT_HIGH_MAX)
        return MVET_U8C_CONT_HIGH;
    if (byte <= MVET_UTF8_OVERLONG2_MAX)
        return MVET_U8C_ILLEGAL;
    if (byte <= MVET_UTF8_LEAD2_MAX)
        return MVET_U8C_LEAD2;
    if (byte == MVET_UTF8_LEAD3_E0)
        return MVET_U8C_LEAD3_E0;
    if (byte == MVET_UTF8_LEAD3_ED)
        return MVET_U8C_LEAD3_ED;
    if (byte <= MVET_UTF8_LEAD3_MAX)
        return MVET_U8C_LEAD3;
    if (byte == MVET_UTF8_LEAD4_F0)
        return MVET_U8C_LEAD4_F0;
    if (byte < MVET_UTF8_LEAD4_F4)
        return MVET_U8C_LEAD4;
    if (byte == MVET_UTF8_LEAD4_F4)
        return MVET_U8C_LEAD4_F4;
    return MVET_U8C_ILLEGAL;
}
