/* ---- src/work.c ---- */
/* work.c: the work counter behind the bounded-work proof, present only
 * in MVET_WORK_PROFILE builds.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai). */

#include <stdint.h>


#ifdef MVET_WORK_PROFILE

/* Deviation from the no-static-mutable-state rule, permitted by the
 * constraint that this counter must observe every module without
 * threading a parameter through validated call chains that the shipping
 * build has no reason to carry. It exists only under MVET_WORK_PROFILE,
 * a test-only build; no shipping object contains this symbol. */
static uint64_t mvet_work_steps;

void mvet_work_add(uint64_t steps)
{
    MVET_ASSERT(mvet_work_steps <= UINT64_MAX - steps);

    mvet_work_steps += steps;
}

uint64_t mvet_work_total(void)
{
    return mvet_work_steps;
}

void mvet_work_reset(void)
{
    mvet_work_steps = 0;
    MVET_ASSERT(mvet_work_steps == 0);
}

#else

/* A translation unit may not be empty; shipping builds compile to this
 * declaration and nothing else. */
_Static_assert(1, "work.c carries no state outside MVET_WORK_PROFILE builds");

#endif /* MVET_WORK_PROFILE */
